window.VARIANTS = [{"id": "v4", "title": "Varianta 4 – model oficial 2026", "theme": "Pierre de Fermat · gândire critică · metabolism", "official": true, "kit": "resurse/kit_varianta4_oficial.zip", "A": [{"id": "I.1.a", "app": "web", "text": "Căutați pe web anul în care Pierre de Fermat a enunțat marea teoremă a lui Fermat, precum și anul în care sir Andrew Wiles a demonstrat-o. Scrieți anii pe foaia de examen și salvați în directorul examen, ca pagină web, numai HTML (HTML only), cu numele implicit, pagina sau paginile de pe care ați preluat informațiile.", "pts": [[2, "Anii scriși corect (1637; 1994/1995)"], [3, "Pagina web salvată ca „HTML only”, cu numele implicit, în examen"]], "sol": {"ms": "Browser: Ctrl+S → Tip: „Pagină web, doar HTML” → folderul examen → Salvare (nu schimbați numele).", "lo": "Firefox: Ctrl+S → „Pagină web, doar HTML”; Chrome: Ctrl+S → „Pagină web, numai HTML”."}, "note": ""}, {"id": "I.1.b", "app": "web", "text": "Copiați în fișierul comp_n un paragraf referitor la marea teoremă a lui Fermat și o imagine cu spirala lui Fermat (spirala parabolică), precum și adresele paginilor web de pe care ați copiat aceste elemente.", "pts": [[2, "Paragraf despre marea teoremă"], [2, "Imagine cu spirala lui Fermat"], [1, "Adresele (URL) paginilor"]], "sol": {"ms": "Selectați paragraful → Ctrl+C → comp_n → Ctrl+V. Imagine: clic dreapta → Copiere imagine → Ctrl+V. Copiați URL-ul din bara de adrese sub fiecare element. Salvați.", "lo": "Identic în LibreOffice Writer (Ctrl+Shift+V → Text neformatat dacă se lipește ciudat)."}, "note": ""}], "B": [{"id": "II.1", "app": "teorie", "text": "Precizați o caracteristică ce diferențiază dispozitivele SSD de cele HDD, precum și un avantaj al utilizării unuia dintre acestea, prin raportare la celălalt.", "pts": [[3, "Caracteristică"], [2, "Avantaj"]], "answer": "SSD stochează datele în memorie flash (fără piese în mișcare), HDD pe platane magnetice rotative citite de un cap mobil. Avantaj SSD: viteză mult mai mare de citire/scriere, rezistență la șocuri, consum redus. (Avantaj HDD: preț pe GB mai mic.)"}, {"id": "II.2", "app": "teorie", "text": "Descrieți, succint, efectul utilizării opțiunilor Răspuns (Reply), respectiv Redirecționare (Forward) în serviciul de e-mail.", "pts": [[3, "Un efect descris corect"], [2, "Al doilea efect descris corect"]], "answer": "Reply: se deschide un mesaj nou adresat automat expeditorului mesajului primit, cu subiectul „Re: …”; atașamentele nu se păstrează. Forward: mesajul primit (cu atașamente) este trimis mai departe către o adresă nouă, completată de utilizator; subiectul devine „Fw: …”."}, {"id": "II.3", "app": "teorie", "text": "Enumerați două tipuri de bare ce pot apărea în componența ferestrei unei aplicații.", "pts": [[3, "Un tip de bară"], [2, "Al doilea tip de bară"]], "answer": "Bara de titlu, bara de meniuri, bara de instrumente (panglica), bara de stare, bara de derulare (scroll)."}, {"id": "III.1.a", "app": "word", "text": "comp_w: Inserați înaintea primului paragraf o reprezentare grafică de tip piramidă, cu trei niveluri: prime (sus), întregi, teoria numerelor (jos), cu fundalurile roșu, galben și verde.", "pts": [[1, "Reprezentare grafică inserată"], [1, "Tip piramidă"], [1, "Structură (3 niveluri)"], [1, "Text poziționat corect"], [1, "Culori roșu/galben/verde"]], "sol": {"ms": "Cursor la începutul doc. → Inserare → SmartArt → Piramidă → Piramidă de bază. Scrieți textele; clic pe fiecare formă → Format formă → Umplere.", "lo": "Nu există SmartArt: desenați 3 forme (Inserare → Formă → triunghi + 2 trapeze) sau o piramidă din Galeria de forme; umplere din Format → Obiect → Zonă."}, "note": ""}, {"id": "III.1.b", "app": "word", "text": "Anulați numerotarea automată pentru paragrafele listei numerotate cu cifre (1., 2., 3. ...) și transformați listele numerotate cu a), b), c) în liste marcate cu marcator •.", "pts": [[2, "Numerotare anulată pentru lista cu cifre"], [1, "Marcatori aplicați"], [1, "Pe listele a), b), c)"], [1, "Marcator de tip •"]], "sol": {"ms": "Selectați lista 1., 2. → Pornire → butonul Numerotare (dezactivat). Selectați listele a) → Pornire → Marcatori → •.", "lo": "Format → Marcatori și numerotare → Niciuna; pentru a): Format → Marcatori și numerotare → Marcatori → •."}, "note": ""}, {"id": "III.1.c", "app": "word", "text": "Înlocuiți în tot documentul literele a și A cu secvența 26, scrisă cu stil aldin (bold).", "pts": [[2, "Cel puțin un tip de litere înlocuit"], [1, "Ambele (a și A)"], [1, "Secvența 26"], [1, "Stil aldin"]], "sol": {"ms": "Ctrl+H → De găsit: a → Înlocuire cu: 26 → Mai multe → Format → Font → Aldin → Înlocuire totală (fără „Potrivire litere mari și mici” ⇒ prinde și A).", "lo": "Ctrl+H → Căutare: a, Înlocuire: 26 → Alte opțiuni → Atribute/Format → Aldin → Înlocuiește tot."}, "note": ""}, {"id": "III.2.a", "app": "ppt", "text": "comp_p: Transformați textul din caseta din mijlocul primului diapozitiv astfel încât să fie scris cu fontul Symbol sau Standard Symbols și subliniat.", "pts": [[2, "Font Symbol / Standard Symbols"], [3, "Subliniere"]], "sol": {"ms": "Selectați caseta → Pornire → Font: Symbol → Ctrl+U.", "lo": "Selectați caseta → Format → Caracter → Font: Standard Symbols PS / OpenSymbol → Efecte → Subliniere."}, "note": ""}, {"id": "III.2.b", "app": "ppt", "text": "Formatați imaginea din diapozitivul 2 astfel încât să aibă o umbră de culoare roșie, pe o distanță de 40 pt / 1,41 cm.", "pts": [[2, "Umbră aplicată"], [3, "Culoare roșie și distanță 40 pt (2p dacă doar un parametru)"]], "sol": {"ms": "Clic dreapta pe imagine → Formatare imagine → Efecte → Umbră → Culoare: roșu, Distanță: 40 pt.", "lo": "Clic dreapta → Zonă… / Format → Umbră (Shadow) → Culoare roșu, Distanță 1,41 cm."}, "note": ""}, {"id": "III.2.c", "app": "ppt", "text": "Creați o expunere particularizată cu numele exp26_213, cu ordinea: al doilea diapozitiv, primul, al treilea.", "pts": [[2, "Expunere particularizată creată"], [1, "Nume exp26_213"], [1, "Diapozitivele incluse"], [1, "Ordinea 2-1-3"]], "sol": {"ms": "Expunere diapozitive → Expunere particularizată → Expuneri particularizate → Nou → nume → adăugați 2, 1, 3 → OK.", "lo": "Expunere → Expunere de diapozitive particularizată → Nou → nume → mutați diapozitivele în ordinea 2, 1, 3."}, "note": ""}, {"id": "III.3.a", "app": "excel", "text": "comp_x: Stabiliți pentru primul rând al foii Document de lucru înălțimea de 100 pt / 3,52 cm și orientați pe verticală conținutul celulelor acestui rând.", "pts": [[3, "Înălțime 100 pt"], [2, "Orientare verticală"]], "sol": {"ms": "Clic dreapta pe antetul rândului 1 → Înălțime rând → 100. Pornire → Orientare (ab↗) → Text vertical.", "lo": "Clic dreapta pe rândul 1 → Înălțime rând → 3,52 cm. Format celule → Aliniere → Text stivuit vertical / 90°."}, "note": ""}, {"id": "III.3.b", "app": "excel", "text": "Inserați în C10 o formulă care afișează numărul de celule din C2:C9 care conțin valori numerice. Copiați formula, cu referințe relative, în B10.", "pts": [[3, "Formula =COUNT(C2:C9) (1p dacă altă formulă)"], [2, "Copiată în B10 (=COUNT(B2:B9))"]], "sol": {"ms": "C10: =COUNT(C2:C9). Ctrl+C pe C10, Ctrl+V în B10 ⇒ =COUNT(B2:B9).", "lo": "C10: =COUNT(C2:C9) (dacă funcțiile sunt traduse, folosiți echivalentul din Asistentul pentru funcții). Copiați în B10."}, "note": ""}, {"id": "III.3.c", "app": "excel", "text": "Stabiliți pentru foaia Document de lucru panoramarea 200% și ordonați filele: Sheet3, Document de lucru, Sheet2.", "pts": [[3, "Zoom 200%"], [2, "Ordinea filelor"]], "sol": {"ms": "Vizualizare → Panoramare → 200%. Trageți filele cu mouse-ul.", "lo": "Vizualizare → Transfocare → 200%. Trageți filele sau clic dreapta → Mută sau copiază foaia."}, "note": ""}, {"id": "III.4.a", "app": "html", "text": "comp_h: Formatați textul primelor două paragrafe ale paginii web cu culoarea fontului verde (green).", "pts": [[3, "Formatare la nivel de font"], [1, "Primele două paragrafe"], [1, "Culoare verde"]], "sol": {"ms": "Deschideți comp_h cu Word (Deschidere cu → Word). Selectați paragrafele → Culoare font → verde. Salvați păstrând formatul HTML.", "lo": "Deschideți cu LibreOffice Writer/Web. Format → Caracter → Efecte de font → Culoare → Verde. Salvați → Păstrează formatul actual."}, "note": ""}, {"id": "III.4.b", "app": "html", "text": "Adăugați pe textul din ultimul paragraf al paginii web o legătură care să deschidă fișierul comp_x.", "pts": [[3, "Legătură adăugată"], [1, "Pe ultimul paragraf"], [1, "Către comp_x"]], "sol": {"ms": "Selectați textul → Ctrl+K → Fișier sau pagină web existentă → comp_x.xlsx → OK. Salvați.", "lo": "Selectați textul → Inserare → Hiperlink (Ctrl+K) → Document → Cale: comp_x.xlsx → OK."}, "note": ""}, {"id": "III.5.a", "app": "access", "text": "comp_a: Sortați datele din interogarea comp_q alfabetic după primul câmp și, pentru valori egale, descrescător după al doilea câmp.", "pts": [[2, "Ordonare aplicată în interogare"], [3, "Crescător pe câmpul 1 + descrescător pe câmpul 2 (2p dacă doar un parametru)"]], "sol": {"ms": "Clic dreapta pe comp_q → Vizualizare proiect → rândul Sortare: Ascendent la primul câmp, Descendent la al doilea (ordinea coloanelor contează) → Salvare.", "lo": "Base: Interogare → Editare → Sortare: crescător / descrescător → Salvare."}, "note": ""}, {"id": "III.5.b", "app": "access", "text": "Realizați un raport cu numele comp_ved pe baza tuturor câmpurilor din tabela comp_t, cu orientarea vedere (landscape).", "pts": [[2, "Raport creat"], [1, "Nume comp_ved"], [1, "Toate câmpurile"], [1, "Orientare vedere"]], "sol": {"ms": "Creare → Expert raport → comp_t → >> → Terminare. Iniţiere pagină → Vedere. Salvați cu numele comp_ved.", "lo": "Base: Rapoarte → Utilizare expert → câmpuri → Aspect → orientare Vedere → nume comp_ved."}, "note": ""}, {"id": "III.6.a", "app": "sistem", "text": "În directorul examen creați o arhivă cu numele wxh26 care să conțină fișierele comp_w, comp_x și comp_h.", "pts": [[3, "Arhivă creată"], [1, "Nume wxh26"], [1, "Cele 3 fișiere"]], "sol": {"ms": "Selectați cele 3 fișiere (Ctrl+clic) → clic dreapta → Trimitere la → Folder comprimat (zip) → redenumiți wxh26.", "lo": "Linux: clic dreapta → Comprimare… → wxh26.zip. 7-Zip: Adăugare la arhivă."}, "note": ""}, {"id": "III.6.b", "app": "sistem", "text": "Vizualizați conținutul directorului examen sub formă de listă și selectați simultan primul și ultimul fișier. Realizați o captură de ecran a ferestrei și salvați imaginea la finalul fișierului comp_w.", "pts": [[1, "Imagine de tip captură"], [2, "Fereastra directorului, afișare Listă"], [2, "Primul și ultimul fișier selectate"]], "sol": {"ms": "Vizualizare → Listă. Clic pe primul, Ctrl+clic pe ultimul. Alt+PrtScn (doar fereastra activă). comp_w → Ctrl+End → Ctrl+V → Salvare.", "lo": "Linux: tasta PrtScn sau Alt+PrtScn → se copiază/salvează imaginea; inserați în comp_w."}, "note": ""}], "pdf": {"A": "resurse/varianta4_fisa_A.pdf", "B": "resurse/varianta4_fisa_B.pdf", "barem": "resurse/varianta4_barem.pdf"}}, {"id": "a1", "title": "Antrenament 1 – Delta Dunării", "theme": "Constantin Brâncuși · Delta Dunării", "official": false, "kit": "resurse/kit_antrenament1.zip", "A": [{"id": "I.1.a", "app": "web", "text": "Căutați pe web anul nașterii sculptorului Constantin Brâncuși și anul în care a fost inaugurată Coloana fără sfârșit de la Târgu Jiu. Scrieți anii pe foaia de examen și salvați în directorul examen, ca pagină web numai HTML, cu numele implicit, pagina/paginile folosite.", "pts": [[2, "Anii corecți (1876; 1938)"], [3, "Pagina salvată ca HTML only, nume implicit, în examen"]], "sol": {"ms": "Ctrl+S în browser → tip „Pagină web, numai HTML” → folderul examen.", "lo": "Idem în Firefox / Chrome pe Linux."}, "note": ""}, {"id": "I.1.b", "app": "web", "text": "Copiați în fișierul comp_n un paragraf despre ansamblul monumental de la Târgu Jiu și o imagine cu Poarta sărutului, precum și adresele paginilor web de pe care le-ați copiat.", "pts": [[2, "Paragraf"], [2, "Imagine"], [1, "Adresele paginilor"]], "sol": {"ms": "Copiere/lipire în comp_n, apoi URL-ul sub fiecare element. Salvați.", "lo": "Idem în LibreOffice Writer."}, "note": ""}], "B": [{"id": "II.1", "app": "teorie", "text": "Precizați două deosebiri între memoria RAM și memoria ROM.", "pts": [[3, "Prima deosebire"], [2, "A doua deosebire"]], "answer": "RAM este volatilă (se golește la oprire), ROM este nevolatilă. RAM poate fi citită și scrisă, ROM (în principiu) doar citită. RAM păstrează programele și datele în lucru; ROM conține firmware-ul de pornire (BIOS/UEFI)."}, {"id": "II.2", "app": "teorie", "text": "Explicați rolul unui program antivirus și dați un exemplu de astfel de program.", "pts": [[3, "Rol"], [2, "Exemplu"]], "answer": "Antivirusul detectează, blochează și elimină programele malițioase (viruși, troieni, ransomware), prin scanarea fișierelor și monitorizare în timp real. Exemple: Windows Defender (Microsoft Defender), Bitdefender, Avast, ESET."}, {"id": "II.3", "app": "teorie", "text": "Enumerați două dispozitive de intrare și două dispozitive de ieșire.", "pts": [[3, "Două dispozitive de intrare"], [2, "Două dispozitive de ieșire"]], "answer": "Intrare: tastatură, mouse, scanner, microfon, cameră web. Ieșire: monitor, imprimantă, boxe, căști, videoproiector."}, {"id": "III.1.a", "app": "word", "text": "comp_w: Stabiliți pentru document orientarea tip vedere (landscape) și marginile stânga și dreapta de 2,5 cm.", "pts": [[2, "Orientare vedere"], [3, "Margini stânga și dreapta 2,5 cm (1p dacă doar una)"]], "sol": {"ms": "Aspect → Orientare → Vedere; Aspect → Margini → Margini particularizate → Stânga/Dreapta 2,5 cm.", "lo": "Format → Stil pagină → Pagină → Orientare: Vedere; Margini stânga/dreapta 2,5 cm."}, "note": ""}, {"id": "III.1.b", "app": "word", "text": "Inserați în antetul documentului textul Delta Dunării, aliniat la dreapta, și în subsol numerotarea paginilor.", "pts": [[2, "Text în antet"], [1, "Aliniere la dreapta"], [2, "Numerotarea paginilor în subsol"]], "sol": {"ms": "Inserare → Antet → Necompletat → scrieți textul → Ctrl+R. Inserare → Număr de pagină → Partea de jos a paginii.", "lo": "Inserare → Antet și subsol → Antet → Implicit; scrieți, aliniați dreapta. Inserare → Antet și subsol → Subsol, apoi Inserare → Câmp → Număr de pagină."}, "note": ""}, {"id": "III.1.c", "app": "word", "text": "Aplicați primului paragraf o literă inițială majusculă (drop cap) pe 3 rânduri și o umbrire (shading) de culoare galbenă.", "pts": [[2, "Literă inițială aplicată"], [1, "Pe 3 rânduri"], [2, "Umbrire galbenă a paragrafului"]], "sol": {"ms": "Inserare → Letrină → Opțiuni letrină → În text, 3 rânduri. Pornire → Umbrire (găleata) → galben.", "lo": "Format → Paragraf → Majuscule încorporate → Afișare, 3 rânduri. Format → Paragraf → Zonă → Culoare galben."}, "note": ""}, {"id": "III.2.a", "app": "ppt", "text": "comp_p: Aplicați tuturor diapozitivelor o tranziție de tip Dizolvare (Dissolve).", "pts": [[2, "Tranziție aplicată"], [2, "Tip Dizolvare"], [1, "Pe toate diapozitivele"]], "sol": {"ms": "Tranziții → Dizolvare (în Mai multe) → Se aplică la toate.", "lo": "Diapozitiv → Tranziție diapozitiv → Dizolvare → Aplică tranziția tuturor diapozitivelor."}, "note": ""}, {"id": "III.2.b", "app": "ppt", "text": "Aplicați imaginii din diapozitivul 2 un efect de animație de intrare de tip Zbor în (Fly In), din partea stângă.", "pts": [[2, "Animație de intrare aplicată imaginii"], [2, "Tip Zbor în"], [1, "Direcția din stânga"]], "sol": {"ms": "Selectați imaginea → Animații → Zbor în → Opțiuni efect → Din stânga.", "lo": "Format → Animație → + → Intrare → Zbor în → Direcție: Din stânga."}, "note": ""}, {"id": "III.2.c", "app": "ppt", "text": "Inserați după al treilea diapozitiv un diapozitiv nou, cu aspectul Doar titlu (Title Only) și titlul Vă mulțumesc!", "pts": [[2, "Diapozitiv inserat"], [1, "Poziția 4"], [1, "Aspect Doar titlu"], [1, "Titlul corect"]], "sol": {"ms": "Selectați diapozitivul 3 → Pornire → Diapozitiv nou → Doar titlu.", "lo": "Diapozitiv → Diapozitiv nou; Aspecte → Doar titlu."}, "note": ""}, {"id": "III.3.a", "app": "excel", "text": "comp_x: Formatați celulele A1:D1 cu stil aldin și umplere de culoare albastru deschis și aplicați bordură tuturor celulelor din A1:D9.", "pts": [[2, "Aldin + umplere pe A1:D1"], [3, "Borduri pe toate celulele A1:D9"]], "sol": {"ms": "Selectați A1:D1 → Ctrl+B → Culoare de umplere. Selectați A1:D9 → Borduri → Toate bordurile.", "lo": "Format celule → Fundal; Format celule → Borduri → Toate bordurile."}, "note": ""}, {"id": "III.3.b", "app": "excel", "text": "Inserați în C10 o formulă care determină automat valoarea maximă din C2:C9. Copiați formula, cu referințe relative, în B10.", "pts": [[3, "=MAX(C2:C9)"], [2, "Copiată în B10"]], "sol": {"ms": "C10: =MAX(C2:C9); copiați în B10 ⇒ =MAX(B2:B9).", "lo": "Identic (funcția MAX)."}, "note": ""}, {"id": "III.3.c", "app": "excel", "text": "Inserați în foaia Sheet2 o diagramă de tip coloană pe baza datelor din A1:B9, cu titlul Suprafața lacurilor.", "pts": [[2, "Diagramă inserată în Sheet2"], [2, "Tip coloană, date A1:B9"], [1, "Titlul"]], "sol": {"ms": "Selectați A1:B9 → Inserare → Coloană. Proiectare diagramă → Mutare diagramă → Sheet2. Clic pe titlu → scrieți.", "lo": "Inserare → Diagramă → Coloană; titlul în pasul Elemente; decupați și lipiți diagrama în Sheet2."}, "note": ""}, {"id": "III.4.a", "app": "html", "text": "comp_h: Aplicați textului primului paragraf stilul aldin (bold) și alinierea centrată.", "pts": [[3, "Aldin"], [2, "Centrat"]], "sol": {"ms": "Deschideți cu Word → Ctrl+B, Ctrl+E → Salvare (format pagină web).", "lo": "Writer/Web → Ctrl+B, Ctrl+E → Păstrează formatul HTML."}, "note": ""}, {"id": "III.4.b", "app": "html", "text": "Inserați la finalul paginii web imaginea din fișierul comp_i.", "pts": [[3, "Imagine inserată"], [2, "La final, fișierul comp_i"]], "sol": {"ms": "Ctrl+End → Inserare → Imagini → comp_i.jpg.", "lo": "Inserare → Imagine → comp_i.jpg (nelegată/legată)."}, "note": ""}, {"id": "III.5.a", "app": "access", "text": "comp_a: Adăugați în tabela comp_t o înregistrare: Specia banane, Glucoză 5, Fructoză 4,9, Magazin Magazin 2.", "pts": [[3, "Înregistrare adăugată"], [2, "Valorile corecte în toate câmpurile"]], "sol": {"ms": "Deschideți comp_t → ultimul rând (*) → scrieți valorile → Enter.", "lo": "Base: Tabele → comp_t → rândul nou."}, "note": ""}, {"id": "III.5.b", "app": "access", "text": "Creați o interogare cu numele comp_m care afișează câmpurile Specia și Magazin, doar pentru înregistrările cu Magazin 1.", "pts": [[2, "Interogare comp_m"], [1, "Câmpurile Specia și Magazin"], [2, "Criteriul \"Magazin 1\""]], "sol": {"ms": "Creare → Proiectare interogare → comp_t → dublu-clic pe câmpuri → Criterii: \"Magazin 1\" → Salvare comp_m.", "lo": "Base: Creare interogare în Vizualizare proiect → Criteriu: 'Magazin 1'."}, "note": ""}, {"id": "III.6.a", "app": "sistem", "text": "În directorul examen creați un subdirector cu numele date26 și copiați în el fișierele comp_d și comp_i.", "pts": [[2, "Subdirector date26"], [3, "Cele două fișiere copiate (nu mutate)"]], "sol": {"ms": "Clic dreapta → Nou → Folder → date26. Selectați fișierele → Ctrl+C → deschideți date26 → Ctrl+V.", "lo": "Idem în managerul de fișiere."}, "note": ""}, {"id": "III.6.b", "app": "sistem", "text": "Vizualizați conținutul directorului examen sub formă de pictograme mari. Realizați o captură a ferestrei și salvați-o la finalul fișierului comp_n.", "pts": [[1, "Captură de ecran"], [2, "Fereastra directorului examen"], [2, "Afișare pictograme mari"]], "sol": {"ms": "Vizualizare → Pictograme mari. Alt+PrtScn → comp_n → Ctrl+End → Ctrl+V.", "lo": "Vizualizare pictograme, zoom mare; captură fereastră."}, "note": ""}]}, {"id": "a2", "title": "Antrenament 2 – Energia regenerabilă", "theme": "Nikola Tesla · surse de energie", "official": false, "kit": "resurse/kit_antrenament2.zip", "A": [{"id": "I.1.a", "app": "web", "text": "Căutați pe web anul nașterii inventatorului Nikola Tesla și anul în care a obținut brevetul pentru motorul electric cu inducție (curent alternativ). Scrieți anii pe foaia de examen și salvați pagina/paginile ca HTML only în examen.", "pts": [[2, "Anii corecți (1856; 1888)"], [3, "Pagina salvată ca HTML only, nume implicit"]], "sol": {"ms": "Ctrl+S → „Pagină web, numai HTML”.", "lo": "Idem."}, "note": ""}, {"id": "I.1.b", "app": "web", "text": "Copiați în comp_n un paragraf despre curentul alternativ și o imagine cu o bobină Tesla, precum și adresele paginilor web.", "pts": [[2, "Paragraf"], [2, "Imagine"], [1, "Adrese"]], "sol": {"ms": "Copiere/lipire + URL.", "lo": "Idem."}, "note": ""}], "B": [{"id": "II.1", "app": "teorie", "text": "Explicați diferența dintre software-ul de sistem și software-ul de aplicație, dând câte un exemplu.", "pts": [[3, "Diferența"], [2, "Exemplele"]], "answer": "Software-ul de sistem gestionează hardware-ul și oferă platforma de rulare (ex.: Windows, Linux, drivere). Software-ul de aplicație rezolvă sarcini ale utilizatorului (ex.: Word, Excel, un browser)."}, {"id": "II.2", "app": "teorie", "text": "Precizați rolul câmpurilor CC și BCC dintr-un mesaj de e-mail.", "pts": [[3, "Rolul CC"], [2, "Rolul BCC"]], "answer": "CC (Carbon Copy): trimite o copie a mesajului altor destinatari, iar adresele lor sunt vizibile tuturor. BCC (Blind Carbon Copy): trimite copii ascunse; ceilalți destinatari nu văd adresele din BCC."}, {"id": "II.3", "app": "teorie", "text": "Precizați două unități de măsură pentru capacitatea de memorare și relația dintre ele.", "pts": [[3, "Două unități"], [2, "Relația"]], "answer": "Byte (octet), kilobyte, megabyte, gigabyte, terabyte. 1 byte = 8 biți; 1 KB = 1024 B; 1 MB = 1024 KB; 1 GB = 1024 MB."}, {"id": "III.1.a", "app": "word", "text": "comp_w: Aplicați întregului document fontul Arial (sau Liberation Sans), dimensiunea 12 și spațierea între rânduri de 1,5.", "pts": [[2, "Font Arial/Liberation Sans, 12"], [3, "Spațiere 1,5 pe tot documentul"]], "sol": {"ms": "Ctrl+A → Font Arial, 12 → Spațiere rânduri 1,5.", "lo": "Ctrl+A → Liberation Sans 12 → Format → Paragraf → Spațiere 1,5 rânduri."}, "note": ""}, {"id": "III.1.b", "app": "word", "text": "Împărțiți al doilea paragraf în două coloane egale, cu linie de separare între ele.", "pts": [[2, "Două coloane"], [1, "Doar paragraful 2"], [2, "Linie de separare"]], "sol": {"ms": "Selectați paragraful → Aspect → Coloane → Mai multe coloane → Două, bifă „Linie între”.", "lo": "Selectați → Format → Coloane → 2, Linie separatoare: continuă."}, "note": ""}, {"id": "III.1.c", "app": "word", "text": "Inserați după ultimul paragraf un tabel cu 3 coloane și 4 rânduri, având pe primul rând: Sursă, Avantaj, Dezavantaj.", "pts": [[2, "Tabel inserat la final"], [2, "3 coloane × 4 rânduri"], [1, "Antetul corect"]], "sol": {"ms": "Ctrl+End → Inserare → Tabel → 3×4.", "lo": "Tabel → Inserare tabel (Ctrl+F12) → 3 coloane, 4 rânduri."}, "note": ""}, {"id": "III.2.a", "app": "ppt", "text": "comp_p: Aplicați tuturor diapozitivelor un fundal de culoare verde deschis.", "pts": [[3, "Fundal verde deschis"], [2, "Pe toate diapozitivele"]], "sol": {"ms": "Proiectare → Formatare fundal → Umplere solidă → verde deschis → Se aplică la toate.", "lo": "Diapozitiv → Proprietăți diapozitiv → Fundal → Culoare → OK → Da, pentru toate paginile."}, "note": ""}, {"id": "III.2.b", "app": "ppt", "text": "Inserați numărul diapozitivului în subsolul tuturor diapozitivelor, cu excepția primului.", "pts": [[3, "Număr diapozitiv inserat"], [2, "Nu apare pe primul (titlu)"]], "sol": {"ms": "Inserare → Antet și subsol → Număr diapozitiv + „Nu se afișează pe diapozitivul titlu” → Se aplică la toate.", "lo": "Inserare → Antet și subsol → Număr diapozitiv + „Nu se afișează pe primul diapozitiv”."}, "note": ""}, {"id": "III.2.c", "app": "ppt", "text": "Inserați pe textul titlului din diapozitivul 3 o legătură către primul diapozitiv.", "pts": [[3, "Legătură inserată pe titlu"], [2, "Destinația: primul diapozitiv"]], "sol": {"ms": "Selectați textul → Ctrl+K → Locație în document → Primul diapozitiv.", "lo": "Ctrl+K → Document → Țintă în document → Diapozitiv 1."}, "note": ""}, {"id": "III.3.a", "app": "excel", "text": "comp_x: Inserați în D2 formula care calculează suma valorilor din B2 și C2 și copiați-o pentru D3:D13.", "pts": [[3, "Formula =B2+C2 sau =SUM(B2:C2)"], [2, "Copiată în D3:D13"]], "sol": {"ms": "D2: =B2+C2 → trageți ghidajul de umplere până la D13.", "lo": "Idem."}, "note": ""}, {"id": "III.3.b", "app": "excel", "text": "Aplicați celulelor B2:B13 o formatare condiționată: valorile mai mari decât 300 să aibă fundal verde.", "pts": [[2, "Formatare condiționată pe B2:B13"], [2, "Condiția > 300"], [1, "Fundal verde"]], "sol": {"ms": "Pornire → Formatare condiționată → Evidențiere reguli celule → Mai mare decât → 300 → Format particularizat → Umplere verde.", "lo": "Format → Condițional → Condiție → valoarea celulei > 300 → Stil nou → Fundal verde."}, "note": ""}, {"id": "III.3.c", "app": "excel", "text": "Redenumiți foaia Sheet2 în Rezumat și înghețați primul rând al foii Document de lucru.", "pts": [[2, "Redenumire Rezumat"], [3, "Primul rând înghețat"]], "sol": {"ms": "Dublu-clic pe filă → Rezumat. Vizualizare → Înghețare panouri → Înghețare rând de sus.", "lo": "Clic dreapta pe filă → Redenumire. Vizualizare → Îngheață celule → Îngheață primul rând."}, "note": ""}, {"id": "III.4.a", "app": "html", "text": "comp_h: Transformați textul primului paragraf în titlu de nivel 1 (Heading 1).", "pts": [[3, "Stil Titlu 1 aplicat"], [2, "Doar primul paragraf"]], "sol": {"ms": "Word: clic în paragraf → Stiluri → Titlu 1.", "lo": "Writer/Web: listă stiluri → Titlu 1 (Ctrl+1)."}, "note": ""}, {"id": "III.4.b", "app": "html", "text": "Inserați după al doilea paragraf o listă marcată cu 3 elemente: soare, vânt, apă.", "pts": [[3, "Listă marcată"], [2, "Poziție și conținut corect"]], "sol": {"ms": "Enter după paragraful 2 → Marcatori → scrieți elementele.", "lo": "Format → Marcatori și numerotare."}, "note": ""}, {"id": "III.5.a", "app": "access", "text": "comp_a: Adăugați în tabela comp_t un câmp nou cu numele Pret, de tip numeric.", "pts": [[3, "Câmp Pret adăugat"], [2, "Tip Număr"]], "sol": {"ms": "comp_t → Vizualizare proiect → rând nou: Pret, Număr → Salvare.", "lo": "Base: Editare tabel → câmp Pret, Zecimal/Număr."}, "note": ""}, {"id": "III.5.b", "app": "access", "text": "Creați un formular cu numele comp_f cu toate câmpurile din comp_t, cu aspect tabelar.", "pts": [[2, "Formular creat"], [1, "Nume comp_f"], [1, "Toate câmpurile"], [1, "Aspect tabelar"]], "sol": {"ms": "Creare → Expert formular → >> → Tabelar → nume comp_f.", "lo": "Base: Formulare → Utilizare expert → Aranjare: Tabelar."}, "note": ""}, {"id": "III.6.a", "app": "sistem", "text": "Redenumiți fișierul comp_d în energie_d și setați-i atributul Doar în citire (read-only).", "pts": [[3, "Redenumit energie_d"], [2, "Atribut Doar în citire"]], "sol": {"ms": "F2 → energie_d. Clic dreapta → Proprietăți → bifă Doar în citire.", "lo": "Linux: Proprietăți → Permisiuni → doar citire."}, "note": ""}, {"id": "III.6.b", "app": "sistem", "text": "Vizualizați conținutul directorului examen sub formă de detalii, sortat descrescător după dimensiune. Salvați o captură a ferestrei la finalul fișierului comp_w.", "pts": [[1, "Captură"], [2, "Afișare detalii"], [2, "Sortare descrescătoare după dimensiune"]], "sol": {"ms": "Vizualizare → Detalii; clic (de 2 ori) pe coloana Dimensiune. Alt+PrtScn.", "lo": "Vizualizare listă; sortare după dimensiune, ordine descrescătoare."}, "note": ""}]}, {"id": "a3", "title": "Antrenament 3 – Ion Creangă", "theme": "Marie Curie · literatură română", "official": false, "kit": "resurse/kit_antrenament3.zip", "A": [{"id": "I.1.a", "app": "web", "text": "Căutați pe web anii în care Marie Curie a primit Premiul Nobel pentru fizică, respectiv pentru chimie. Scrieți anii pe foaia de examen și salvați pagina/paginile ca HTML only în examen.", "pts": [[2, "Anii corecți (1903; 1911)"], [3, "Pagina salvată ca HTML only"]], "sol": {"ms": "Ctrl+S → numai HTML.", "lo": "Idem."}, "note": ""}, {"id": "I.1.b", "app": "web", "text": "Copiați în comp_n un paragraf despre descoperirea radioactivității și o imagine cu Marie Curie în laborator, precum și adresele paginilor web.", "pts": [[2, "Paragraf"], [2, "Imagine"], [1, "Adrese"]], "sol": {"ms": "Copiere/lipire + URL.", "lo": "Idem."}, "note": ""}], "B": [{"id": "II.1", "app": "teorie", "text": "Explicați ce este o arhivă și precizați un avantaj al arhivării fișierelor.", "pts": [[3, "Definiție"], [2, "Avantaj"]], "answer": "O arhivă este un fișier care conține unul sau mai multe fișiere/foldere, de obicei comprimate (.zip, .rar, .7z). Avantaje: ocupă mai puțin spațiu, se transmit mai ușor (un singur fișier, ex. ca atașament), pot fi protejate cu parolă."}, {"id": "II.2", "app": "teorie", "text": "Ce este phishing-ul? Precizați o măsură de protecție.", "pts": [[3, "Definiție"], [2, "Măsură"]], "answer": "Phishing-ul este o tentativă de fraudă prin mesaje (e-mail, SMS) sau site-uri false care imită instituții reale pentru a obține parole, date de card etc. Protecție: verificarea adresei expeditorului și a linkului, nu se introduc date personale din linkuri primite, autentificare în doi pași."}, {"id": "II.3", "app": "teorie", "text": "Explicați diferența dintre un browser și un motor de căutare, cu câte un exemplu.", "pts": [[3, "Diferența"], [2, "Exemplele"]], "answer": "Browserul este aplicația care afișează paginile web (Chrome, Firefox, Edge). Motorul de căutare este un site/serviciu care găsește pagini după cuvinte cheie (Google, Bing, DuckDuckGo)."}, {"id": "III.1.a", "app": "word", "text": "comp_w: Inserați o notă de subsol pe cuvântul Humulești din primul paragraf, cu textul: sat din județul Neamț.", "pts": [[3, "Notă de subsol inserată"], [1, "Pe cuvântul Humulești"], [1, "Textul notei"]], "sol": {"ms": "Cursor după cuvânt → Referințe → Inserare notă de subsol → scrieți textul.", "lo": "Inserare → Notă de subsol și notă de final → Notă de subsol."}, "note": ""}, {"id": "III.1.b", "app": "word", "text": "Aplicați paragrafelor listei marcate o indentare la stânga de 2 cm și spațiere după paragraf de 6 pt.", "pts": [[3, "Indentare stânga 2 cm"], [2, "Spațiere după 6 pt"]], "sol": {"ms": "Selectați lista → Paragraf → Indentare Stânga 2 cm, După: 6 pt.", "lo": "Format → Paragraf → Indentări și spațiere."}, "note": ""}, {"id": "III.1.c", "app": "word", "text": "Inserați în document un filigran (watermark) text cu cuvântul CREANGĂ.", "pts": [[3, "Filigran inserat"], [2, "Textul CREANGĂ"]], "sol": {"ms": "Proiectare → Filigran → Filigran particularizat → Text.", "lo": "Format → Filigran → Text."}, "note": ""}, {"id": "III.2.a", "app": "ppt", "text": "comp_p: Schimbați aspectul diapozitivului 3 în Două conținuturi (Two Content) și inserați în partea dreaptă imaginea comp_i.", "pts": [[2, "Aspect Două conținuturi"], [3, "Imaginea comp_i în partea dreaptă"]], "sol": {"ms": "Pornire → Aspect → Două conținuturi; în caseta dreaptă → pictograma Imagini → comp_i.", "lo": "Aspecte → Titlu, 2 conținuturi; Inserare → Imagine."}, "note": ""}, {"id": "III.2.b", "app": "ppt", "text": "Aplicați titlului din primul diapozitiv efectul de animație de evidențiere Rotire (Spin).", "pts": [[2, "Animație pe titlu"], [3, "Tip evidențiere Rotire"]], "sol": {"ms": "Selectați titlul → Animații → Evidențiere → Rotire.", "lo": "Format → Animație → + → Evidențiere → Rotire."}, "note": ""}, {"id": "III.2.c", "app": "ppt", "text": "Ascundeți al doilea diapozitiv la expunere.", "pts": [[5, "Diapozitivul 2 ascuns"]], "sol": {"ms": "Clic dreapta pe miniatură → Ascundere diapozitiv.", "lo": "Clic dreapta → Ascunde diapozitivul."}, "note": ""}, {"id": "III.3.a", "app": "excel", "text": "comp_x: Sortați datele din A1:D9 crescător după coloana An apariție.", "pts": [[2, "Sortare aplicată întregului tabel"], [3, "Crescător după An apariție"]], "sol": {"ms": "Selectați A1:D9 → Date → Sortare → După: An apariție, De la cel mai mic la cel mai mare.", "lo": "Date → Sortare → Cheie 1: An apariție, Crescător."}, "note": ""}, {"id": "III.3.b", "app": "excel", "text": "Inserați în E2 o formulă care afișează textul lungă dacă numărul de pagini este mai mare decât 100, altfel scurtă. Copiați formula până la E9.", "pts": [[3, "=IF(C2>100;\"lungă\";\"scurtă\")"], [2, "Copiată E3:E9"]], "sol": {"ms": "E2: =IF(C2>100,\"lungă\",\"scurtă\") → trageți până la E9.", "lo": "E2: =IF(C2>100;\"lungă\";\"scurtă\") (separator ; )."}, "note": ""}, {"id": "III.3.c", "app": "excel", "text": "Stabiliți pentru foaia de lucru orientarea tipăririi vedere și centrarea pe orizontală a paginii.", "pts": [[3, "Orientare vedere"], [2, "Centrare orizontală"]], "sol": {"ms": "Aspect pagină → Orientare → Vedere; Inițializare pagină → Margini → Centrare pe pagină: Orizontal.", "lo": "Format → Stil pagină → Pagină → Vedere, Aliniere tabel: Orizontal."}, "note": ""}, {"id": "III.4.a", "app": "html", "text": "comp_h: Schimbați culoarea de fundal a paginii web în galben deschis.", "pts": [[3, "Fundal pagină schimbat"], [2, "Galben deschis"]], "sol": {"ms": "Word: Proiectare → Culoare pagină → galben deschis.", "lo": "Writer/Web: Format → Stil pagină → Zonă → Culoare."}, "note": ""}, {"id": "III.4.b", "app": "html", "text": "Inserați după ultimul paragraf un tabel cu 2 rânduri și 2 coloane.", "pts": [[3, "Tabel inserat"], [2, "2×2, după ultimul paragraf"]], "sol": {"ms": "Ctrl+End → Inserare → Tabel 2×2.", "lo": "Ctrl+F12 → 2×2."}, "note": ""}, {"id": "III.5.a", "app": "access", "text": "comp_a: Sortați înregistrările tabelei comp_t descrescător după câmpul Glucoză și salvați tabela.", "pts": [[2, "Sortare aplicată"], [3, "Descrescător după Glucoză"]], "sol": {"ms": "Deschideți comp_t → clic în coloană → Pornire → Descendent → Ctrl+S.", "lo": "Base: tabel deschis → Sortare descendentă."}, "note": ""}, {"id": "III.5.b", "app": "access", "text": "Creați o interogare cu numele comp_g care afișează câmpurile Specia și Fructoză pentru înregistrările cu Glucoză mai mare decât 2.", "pts": [[2, "Interogare comp_g"], [1, "Câmpuri Specia, Fructoză"], [2, "Criteriul >2 pe Glucoză (neafișat)"]], "sol": {"ms": "Proiectare interogare → Specia, Fructoză, Glucoză (debifat Afișare) → Criterii: >2.", "lo": "Base: Vizualizare proiect → Criteriu >2, Vizibil debifat."}, "note": ""}, {"id": "III.6.a", "app": "sistem", "text": "Creați în directorul examen o comandă rapidă (shortcut) către fișierul comp_p.", "pts": [[3, "Comandă rapidă creată"], [2, "În examen, către comp_p"]], "sol": {"ms": "Clic dreapta pe comp_p → Afișare mai multe opțiuni → Creare comandă rapidă.", "lo": "Linux: clic dreapta → Creează legătură."}, "note": ""}, {"id": "III.6.b", "app": "sistem", "text": "Deschideți fereastra Proprietăți (Properties) a fișierului comp_x și salvați o captură a acesteia la finalul fișierului comp_n.", "pts": [[1, "Captură"], [4, "Fereastra Proprietăți a lui comp_x"]], "sol": {"ms": "Clic dreapta → Proprietăți → Alt+PrtScn → comp_n → Ctrl+V.", "lo": "Idem."}, "note": ""}]}, {"id": "a4", "title": "Antrenament 4 – Sistemul circulator", "theme": "Henri Coandă · biologie", "official": false, "kit": "resurse/kit_antrenament4.zip", "A": [{"id": "I.1.a", "app": "web", "text": "Căutați pe web anul nașterii inginerului Henri Coandă și anul în care a fost prezentat avionul Coandă-1910. Scrieți anii pe foaia de examen și salvați pagina/paginile ca HTML only în examen.", "pts": [[2, "Anii corecți (1886; 1910)"], [3, "Pagina salvată ca HTML only"]], "sol": {"ms": "Ctrl+S → numai HTML.", "lo": "Idem."}, "note": ""}, {"id": "I.1.b", "app": "web", "text": "Copiați în comp_n un paragraf despre efectul Coandă și o imagine cu avionul Coandă-1910, precum și adresele paginilor web.", "pts": [[2, "Paragraf"], [2, "Imagine"], [1, "Adrese"]], "sol": {"ms": "Copiere/lipire + URL.", "lo": "Idem."}, "note": ""}], "B": [{"id": "II.1", "app": "teorie", "text": "Precizați rolul procesorului (CPU) și o caracteristică ce îi influențează performanța.", "pts": [[3, "Rol"], [2, "Caracteristică"]], "answer": "Procesorul execută instrucțiunile programelor și coordonează funcționarea celorlalte componente. Caracteristici: frecvența (GHz), numărul de nuclee, memoria cache."}, {"id": "II.2", "app": "teorie", "text": "Precizați două reguli pentru crearea unei parole sigure.", "pts": [[3, "Prima regulă"], [2, "A doua regulă"]], "answer": "Minimum 12 caractere; combinație de litere mari, mici, cifre și simboluri; fără date personale (nume, zi de naștere); parole diferite pentru conturi diferite; schimbare dacă a fost compromisă."}, {"id": "II.3", "app": "teorie", "text": "Explicați ce reprezintă extensia unui fișier și dați două exemple, cu tipul asociat.", "pts": [[3, "Explicație"], [2, "Exemple"]], "answer": "Extensia este secvența de după ultimul punct din numele fișierului și indică tipul/formatul acestuia (și aplicația care îl deschide). Ex.: .docx – document Word, .xlsx – registru Excel, .jpg – imagine, .html – pagină web, .zip – arhivă."}, {"id": "III.1.a", "app": "word", "text": "comp_w: Aplicați paginilor documentului o bordură de pagină cu linie dublă, de culoare roșie.", "pts": [[2, "Bordură de pagină"], [2, "Linie dublă"], [1, "Culoare roșie"]], "sol": {"ms": "Proiectare → Borduri de pagină → Casetă, stil linie dublă, culoare roșie.", "lo": "Format → Stil pagină → Borduri → linie dublă, roșu."}, "note": ""}, {"id": "III.1.b", "app": "word", "text": "Aplicați primelor două paragrafe alinierea stânga-dreapta (justify) și indentarea primului rând de 1,25 cm.", "pts": [[2, "Aliniere stânga-dreapta"], [3, "Indentare prim rând 1,25 cm"]], "sol": {"ms": "Selectați → Ctrl+J → Paragraf → Special: Primul rând 1,25 cm.", "lo": "Format → Paragraf → Aliniere: Stânga-dreapta; Primul rând 1,25 cm."}, "note": ""}, {"id": "III.1.c", "app": "word", "text": "Inserați un comentariu pe cuvântul inima din al doilea paragraf, cu textul organ central.", "pts": [[3, "Comentariu inserat"], [2, "Pe cuvântul corect, cu textul cerut"]], "sol": {"ms": "Selectați cuvântul → Revizuire → Comentariu nou.", "lo": "Inserare → Comentariu (Ctrl+Alt+C)."}, "note": ""}, {"id": "III.2.a", "app": "ppt", "text": "comp_p: Aplicați imaginii din diapozitivul 2 un contur roșu cu grosimea de 6 pt.", "pts": [[2, "Contur aplicat"], [2, "Culoare roșie"], [1, "Grosime 6 pt"]], "sol": {"ms": "Format imagine → Bordură imagine → roșu; Grosime → 6 pt.", "lo": "Clic dreapta → Linie → Culoare roșu, Lățime 0,21 cm (6 pt)."}, "note": ""}, {"id": "III.2.b", "app": "ppt", "text": "Setați tranzițiile astfel încât fiecare diapozitiv să avanseze automat după 5 secunde.", "pts": [[3, "Avans automat"], [2, "5 secunde, pe toate"]], "sol": {"ms": "Tranziții → Avansare diapozitiv: După 00:05 → Se aplică la toate.", "lo": "Tranziție diapozitiv → Automat după 5 sec → Aplică tuturor."}, "note": ""}, {"id": "III.2.c", "app": "ppt", "text": "Inserați în diapozitivul 3 o formă de tip săgeată dreapta, cu textul circulație.", "pts": [[3, "Săgeată dreapta"], [2, "Textul în formă"]], "sol": {"ms": "Inserare → Forme → Săgeată dreapta → desenați → scrieți textul.", "lo": "Săgeți bloc → Săgeată dreapta → dublu-clic → text."}, "note": ""}, {"id": "III.3.a", "app": "excel", "text": "comp_x: Îmbinați și centrați celulele A11:D11 și scrieți în ele textul Date de exercițiu.", "pts": [[3, "Îmbinare și centrare A11:D11"], [2, "Textul"]], "sol": {"ms": "Selectați A11:D11 → Pornire → Îmbinare și centrare.", "lo": "Format → Îmbinare și dezîmbinare celule → Îmbinare și centrare."}, "note": ""}, {"id": "III.3.b", "app": "excel", "text": "Inserați în C10 o formulă care calculează media valorilor din C2:C9. Copiați formula în D10.", "pts": [[3, "=AVERAGE(C2:C9)"], [2, "Copiată în D10"]], "sol": {"ms": "C10: =AVERAGE(C2:C9) → copiere în D10.", "lo": "=AVERAGE(C2:C9); copiere în D10."}, "note": ""}, {"id": "III.3.c", "app": "excel", "text": "Aplicați filtrare automată pe A1:D9 și afișați doar elevii cu vârsta mai mare decât 16.", "pts": [[2, "Filtru automat"], [3, "Condiția Vârstă > 16"]], "sol": {"ms": "Date → Filtru → săgeata Vârstă → Filtre numerice → Mai mare decât 16.", "lo": "Date → Filtru automat → Filtru standard: Vârstă > 16."}, "note": ""}, {"id": "III.4.a", "app": "html", "text": "comp_h: Stabiliți pentru textul întregii pagini fontul Verdana (sau DejaVu Sans) și dimensiunea 14.", "pts": [[3, "Font"], [2, "Dimensiune 14"]], "sol": {"ms": "Ctrl+A → font Verdana, 14.", "lo": "Ctrl+A → DejaVu Sans, 14."}, "note": ""}, {"id": "III.4.b", "app": "html", "text": "Adăugați pe textul primului paragraf o legătură către adresa https://www.edu.ro.", "pts": [[3, "Legătură"], [2, "Adresa corectă, primul paragraf"]], "sol": {"ms": "Ctrl+K → Adresă → https://www.edu.ro.", "lo": "Ctrl+K → Internet → URL."}, "note": ""}, {"id": "III.5.a", "app": "access", "text": "comp_a: Stabiliți câmpul Specia drept cheie primară a tabelei comp_t.", "pts": [[5, "Cheie primară pe Specia"]], "sol": {"ms": "comp_t → Vizualizare proiect → selectați Specia → Cheie primară → Salvare.", "lo": "Base: Editare → clic dreapta pe rând → Cheie primară."}, "note": ""}, {"id": "III.5.b", "app": "access", "text": "Realizați un raport cu numele comp_r pe baza câmpurilor Specia și Glucoză, cu grupare după Magazin.", "pts": [[2, "Raport comp_r"], [1, "Câmpurile Specia, Glucoză"], [2, "Grupare după Magazin"]], "sol": {"ms": "Expert raport → Specia, Glucoză, Magazin → nivel grupare: Magazin → nume comp_r.", "lo": "Base: Expert rapoarte → Grupare → Magazin."}, "note": ""}, {"id": "III.6.a", "app": "sistem", "text": "Creați în directorul examen o arhivă cu numele biologie26, care să conțină fișierele comp_p și comp_i.", "pts": [[3, "Arhivă"], [1, "Nume"], [1, "Fișierele corecte"]], "sol": {"ms": "Selectare → Trimitere la → Folder comprimat → redenumire.", "lo": "Comprimare… → biologie26.zip."}, "note": ""}, {"id": "III.6.b", "app": "sistem", "text": "Căutați în directorul examen toate fișierele cu extensia .docx. Salvați o captură a ferestrei cu rezultatele căutării la finalul fișierului comp_n.", "pts": [[1, "Captură"], [4, "Rezultatele căutării *.docx vizibile"]], "sol": {"ms": "Caseta Căutare din Explorer: *.docx → Alt+PrtScn.", "lo": "Căutare (Ctrl+F) în managerul de fișiere: .docx."}, "note": ""}]}, {"id": "a5", "title": "Antrenament 5 – Unirea Principatelor", "theme": "Ana Aslan · istorie", "official": false, "kit": "resurse/kit_antrenament5.zip", "A": [{"id": "I.1.a", "app": "web", "text": "Căutați pe web anul nașterii medicului Ana Aslan și anul în care a creat produsul Gerovital H3. Scrieți anii pe foaia de examen și salvați pagina/paginile ca HTML only în examen.", "pts": [[2, "Anii corecți (1897; 1952)"], [3, "Pagina salvată ca HTML only"]], "sol": {"ms": "Ctrl+S → numai HTML.", "lo": "Idem."}, "note": ""}, {"id": "I.1.b", "app": "web", "text": "Copiați în comp_n un paragraf despre gerontologie și o imagine cu Ana Aslan, precum și adresele paginilor web.", "pts": [[2, "Paragraf"], [2, "Imagine"], [1, "Adrese"]], "sol": {"ms": "Copiere/lipire + URL.", "lo": "Idem."}, "note": ""}], "B": [{"id": "II.1", "app": "teorie", "text": "Precizați ce este o rețea de calculatoare de tip LAN și un avantaj al utilizării ei.", "pts": [[3, "Definiție"], [2, "Avantaj"]], "answer": "LAN (Local Area Network) este o rețea care conectează calculatoare aflate pe o arie restrânsă (laborator, școală, casă). Avantaje: partajarea fișierelor, a imprimantelor și a conexiunii la Internet, comunicare rapidă."}, {"id": "II.2", "app": "teorie", "text": "Ce este un fișier atașat (attachment) la un mesaj de e-mail? Precizați o măsură de precauție.", "pts": [[3, "Definiție"], [2, "Măsură"]], "answer": "Un fișier trimis împreună cu mesajul (document, imagine, arhivă). Precauție: nu se deschid atașamente de la expeditori necunoscuți sau cu extensii suspecte (.exe), se scanează cu antivirusul."}, {"id": "II.3", "app": "teorie", "text": "Precizați efectul combinațiilor de taste Ctrl+C, Ctrl+V și Ctrl+Z.", "pts": [[3, "Două efecte corecte"], [2, "Al treilea efect"]], "answer": "Ctrl+C – copiază selecția în clipboard; Ctrl+V – lipește conținutul clipboard-ului; Ctrl+Z – anulează ultima acțiune."}, {"id": "III.1.a", "app": "word", "text": "comp_w: Inserați la sfârșitul documentului o întrerupere de pagină, iar pe pagina nouă scrieți textul Bibliografie.", "pts": [[3, "Întrerupere de pagină la final"], [2, "Textul pe pagina nouă"]], "sol": {"ms": "Ctrl+End → Ctrl+Enter → scrieți.", "lo": "Ctrl+End → Inserare → Mai multe întreruperi → Întrerupere de pagină (Ctrl+Enter)."}, "note": ""}, {"id": "III.1.b", "app": "word", "text": "Transformați lista marcată într-o listă numerotată cu cifre romane (I, II, III ...).", "pts": [[2, "Listă numerotată"], [3, "Format I, II, III"]], "sol": {"ms": "Selectați → Numerotare → Bibliotecă → I. II. III.", "lo": "Format → Marcatori și numerotare → Numerotare → I, II, III."}, "note": ""}, {"id": "III.1.c", "app": "word", "text": "Stabiliți pentru ultimul paragraf spațierea între caractere extinsă cu 2 pt și efectul majuscule mici (small caps).", "pts": [[3, "Spațiere extinsă 2 pt"], [2, "Majuscule mici"]], "sol": {"ms": "Font (Ctrl+D) → Complex → Spațiere Extinsă 2 pt; Efecte → Majuscule mici.", "lo": "Format → Caracter → Poziție → Spațiere 2 pt; Efecte → Majuscule mici."}, "note": ""}, {"id": "III.2.a", "app": "ppt", "text": "comp_p: Duplicați al doilea diapozitiv și mutați copia la finalul prezentării.", "pts": [[3, "Diapozitiv duplicat"], [2, "Copia la final"]], "sol": {"ms": "Clic dreapta → Dublare diapozitiv → trageți la final.", "lo": "Diapozitiv → Dublare diapozitiv → Diapozitiv → Mutare → la final."}, "note": ""}, {"id": "III.2.b", "app": "ppt", "text": "Aplicați textului din diapozitivul 3 un efect de animație de ieșire Estompare (Fade), declanșat la clic.", "pts": [[2, "Animație de ieșire"], [2, "Tip Estompare"], [1, "Pornire la clic"]], "sol": {"ms": "Animații → Ieșire → Estompare; Pornire: La clic.", "lo": "Format → Animație → Ieșire → Estompare; Pornire: La clic."}, "note": ""}, {"id": "III.2.c", "app": "ppt", "text": "Salvați prezentarea și în format PDF, cu numele istorie26, în directorul examen.", "pts": [[3, "Fișier PDF"], [2, "Nume istorie26, în examen"]], "sol": {"ms": "Fișier → Salvare ca → Tip: PDF.", "lo": "Fișier → Export în PDF."}, "note": ""}, {"id": "III.3.a", "app": "excel", "text": "comp_x: Inserați o coloană nouă între coloanele C și D, cu antetul Durată, în care să calculați An2 − An1 pentru fiecare eveniment.", "pts": [[2, "Coloană inserată, antet Durată"], [3, "Formula =C2-B2 copiată"]], "sol": {"ms": "Clic dreapta pe D → Inserare → D1: Durată, D2: =C2-B2, copiere.", "lo": "Foaie → Inserare coloane → Înainte."}, "note": ""}, {"id": "III.3.b", "app": "excel", "text": "Aplicați celulelor B2:B9 o formatare condiționată de tip bare de date (data bars).", "pts": [[2, "Formatare condiționată"], [3, "Bare de date pe B2:B9"]], "sol": {"ms": "Formatare condiționată → Bare de date.", "lo": "Format → Condițional → Bară de date."}, "note": ""}, {"id": "III.3.c", "app": "excel", "text": "Stabiliți zona de imprimare A1:D9 și inserați în antetul foii textul Istorie.", "pts": [[3, "Zonă de imprimare"], [2, "Antet cu textul Istorie"]], "sol": {"ms": "Aspect pagină → Zonă imprimare → Stabilire. Inserare → Antet și subsol.", "lo": "Format → Zone de imprimare → Definire. Inserare → Antete și subsoluri."}, "note": ""}, {"id": "III.4.a", "app": "html", "text": "comp_h: Stabiliți titlul paginii web (elementul title) Hora Unirii 2026.", "pts": [[5, "Titlul paginii modificat"]], "sol": {"ms": "Word: Fișier → Informații → Proprietăți → Titlu (sau în Salvare ca → Modificare titlu).", "lo": "Writer/Web: Fișier → Proprietăți → Descriere → Titlu."}, "note": ""}, {"id": "III.4.b", "app": "html", "text": "Formatați textul ultimului paragraf cu stil cursiv (italic) și subliniat.", "pts": [[3, "Cursiv"], [2, "Subliniat"]], "sol": {"ms": "Ctrl+I, Ctrl+U.", "lo": "Idem."}, "note": ""}, {"id": "III.5.a", "app": "access", "text": "comp_a: Modificați dimensiunea câmpului Magazin din tabela comp_t la 20 de caractere.", "pts": [[5, "Dimensiune câmp 20"]], "sol": {"ms": "Vizualizare proiect → Magazin → Dimensiune câmp: 20.", "lo": "Base: Editare → Proprietăți câmp → Lungime 20."}, "note": ""}, {"id": "III.5.b", "app": "access", "text": "Creați o interogare cu numele comp_c care afișează Specia și un câmp calculat Total, egal cu suma valorilor din Glucoză și Fructoză.", "pts": [[2, "Interogare comp_c"], [3, "Câmp calculat Total: [Glucoză]+[Fructoză]"]], "sol": {"ms": "Proiectare interogare → Specia; coloană nouă: Total: [Glucoză]+[Fructoză].", "lo": "Base: câmp \"Glucoză\"+\"Fructoză\", Alias: Total."}, "note": ""}, {"id": "III.6.a", "app": "sistem", "text": "Creați în directorul examen subdirectorul arhiva26 și mutați în el fișierul comp_d.", "pts": [[2, "Subdirector"], [3, "Fișier mutat (nu copiat)"]], "sol": {"ms": "Ctrl+X pe comp_d → arhiva26 → Ctrl+V.", "lo": "Idem sau trageți cu Shift."}, "note": ""}, {"id": "III.6.b", "app": "sistem", "text": "Vizualizați conținutul directorului examen sub formă de detalii și selectați simultan fișierele comp_p și comp_x. Salvați o captură a ferestrei la finalul fișierului comp_n.", "pts": [[1, "Captură"], [2, "Afișare detalii"], [2, "Selecția celor 2 fișiere"]], "sol": {"ms": "Vizualizare → Detalii; Ctrl+clic. Alt+PrtScn.", "lo": "Idem."}, "note": ""}]}, {"id": "a6", "title": "Antrenament 6 – Mihai Eminescu", "theme": "Nicolae Paulescu · literatură", "official": false, "kit": "resurse/kit_antrenament6.zip", "A": [{"id": "I.1.a", "app": "web", "text": "Căutați pe web anul nașterii savantului Nicolae Paulescu și anul în care a publicat descoperirea pancreinei. Scrieți anii pe foaia de examen și salvați în directorul examen, ca pagină web numai HTML (HTML only), cu numele implicit, pagina/paginile folosite.", "pts": [[2, "Anii corecți (1869; 1921)"], [3, "Pagina salvată ca HTML only, nume implicit, în examen"]], "sol": {"ms": "Ctrl+S în browser → tip „Pagină web, numai HTML” → folderul examen → Salvare.", "lo": "Firefox: „Pagină web, doar HTML”; Chrome: „Pagină web, numai HTML”."}, "note": ""}, {"id": "I.1.b", "app": "web", "text": "Copiați în fișierul comp_n un paragraf despre descoperirea pancreinei și o imagine cu Nicolae Paulescu, precum și adresele paginilor web de pe care le-ați copiat.", "pts": [[2, "Paragraf"], [2, "Imagine"], [1, "Adresele paginilor"]], "sol": {"ms": "Copiere/lipire în comp_n, apoi URL-ul sub fiecare element. Salvați.", "lo": "Idem în LibreOffice Writer."}, "note": ""}], "B": [{"id": "II.1", "app": "teorie", "text": "Explicați ce este un driver și dați un exemplu de dispozitiv care are nevoie de el.", "pts": [[3, "Definiție"], [2, "Exemplu"]], "answer": "Program care permite sistemului de operare să comunice cu un dispozitiv hardware. Exemple: imprimanta, placa video, placa de sunet."}, {"id": "II.2", "app": "teorie", "text": "Precizați diferența dintre opțiunile Reply și Reply All din serviciul de e-mail.", "pts": [[3, "Reply"], [2, "Reply All"]], "answer": "Reply trimite răspunsul doar expeditorului mesajului; Reply All îl trimite expeditorului și tuturor celorlalți destinatari ai mesajului inițial."}, {"id": "II.3", "app": "teorie", "text": "Precizați două funcții ale unui sistem de operare.", "pts": [[3, "Prima funcție"], [2, "A doua funcție"]], "answer": "Gestionează resursele hardware (procesor, memorie), gestionează fișierele și directoarele, oferă interfața cu utilizatorul, lansează și controlează aplicațiile."}, {"id": "III.1.a", "app": "word", "text": "comp_w: Aplicați cuvântului Luceafărul din al treilea paragraf o evidențiere (highlight) de culoare galbenă și stilul cursiv.", "pts": [[3, "Evidențiere galbenă"], [2, "Cursiv, doar pe cuvântul indicat"]], "sol": {"ms": "Selectați cuvântul → Pornire → Culoare evidențiere text → Galben; Ctrl+I.", "lo": "Format → Caracter → Evidențiere → Galben; Ctrl+I."}, "note": ""}, {"id": "III.1.b", "app": "word", "text": "Transformați lista numerotată într-o listă marcată cu marcatorul ► (săgeată).", "pts": [[2, "Listă marcată"], [3, "Marcator de tip ►"]], "sol": {"ms": "Selectați lista → Marcatori → Definire marcator nou → Simbol → ►.", "lo": "Format → Marcatori și numerotare → Marcatori / Personalizare → Caracter ►."}, "note": ""}, {"id": "III.1.c", "app": "word", "text": "Inserați la începutul documentului un obiect WordArt (Fontwork) cu textul Eminescu.", "pts": [[3, "WordArt / Fontwork inserat"], [2, "La început, cu textul corect"]], "sol": {"ms": "Ctrl+Home → Inserare → WordArt → scrieți textul.", "lo": "Inserare → Fontwork → alegeți un stil → dublu-clic și scrieți textul."}, "note": ""}, {"id": "III.2.a", "app": "ppt", "text": "comp_p: Aplicați prezentării o temă (design) la alegere, pe toate diapozitivele.", "pts": [[3, "Temă aplicată"], [2, "Pe toate diapozitivele"]], "sol": {"ms": "Proiectare → alegeți o temă (se aplică tuturor).", "lo": "Diapozitiv → Modifică șablonul / panoul Pagini model → Aplică tuturor."}, "note": ""}, {"id": "III.2.b", "app": "ppt", "text": "Inserați în diapozitivul 3 un tabel cu 2 coloane și 3 rânduri.", "pts": [[3, "Tabel inserat"], [2, "2 coloane × 3 rânduri, pe diapozitivul 3"]], "sol": {"ms": "Inserare → Tabel → 2×3.", "lo": "Inserare → Tabel → 2 coloane, 3 rânduri."}, "note": ""}, {"id": "III.2.c", "app": "ppt", "text": "Stabiliți pentru tranziția diapozitivului 2 efectul Împingere (Push) cu durata de 2 secunde.", "pts": [[3, "Tranziție Împingere pe diapozitivul 2"], [2, "Durata 2 secunde"]], "sol": {"ms": "Tranziții → Împingere → Durată: 02,00.", "lo": "Tranziție diapozitiv → Împinge → Durată 2 s."}, "note": ""}, {"id": "III.3.a", "app": "excel", "text": "comp_x: Stabiliți pentru coloana A lățimea de 30 de caractere și încadrați textul (wrap text) în celulele A1:D1.", "pts": [[3, "Lățime coloană A"], [2, "Încadrare text A1:D1"]], "sol": {"ms": "Clic dreapta pe antetul A → Lățime coloană → 30; Pornire → Încadrare text.", "lo": "Clic dreapta → Lățime coloană; Format celule → Aliniere → Încadrare automată."}, "note": ""}, {"id": "III.3.b", "app": "excel", "text": "Inserați în C10 o formulă care calculează numărul total de strofe din C2:C9, iar în C11 o formulă care afișează numărul de celule goale din C2:C9.", "pts": [[3, "C10: =SUM(C2:C9)"], [2, "C11: =COUNTBLANK(C2:C9)"]], "sol": {"ms": "C10: =SUM(C2:C9); C11: =COUNTBLANK(C2:C9).", "lo": "Idem."}, "note": ""}, {"id": "III.3.c", "app": "excel", "text": "Creați o copie a foii Document de lucru, plasată la finalul registrului, cu numele Copie.", "pts": [[3, "Copie a foii"], [2, "La final, numele Copie"]], "sol": {"ms": "Clic dreapta pe filă → Mutare sau copiere → (mutare la sfârșit) + Crearea unei copii → redenumire.", "lo": "Clic dreapta → Mută sau copiază foaia → Copiază, Poziție: la sfârșit, Nume nou: Copie."}, "note": ""}, {"id": "III.4.a", "app": "html", "text": "comp_h: Transformați al doilea și al treilea paragraf într-o listă numerotată.", "pts": [[3, "Listă numerotată"], [2, "Doar paragrafele 2 și 3"]], "sol": {"ms": "Selectați → Numerotare.", "lo": "Format → Marcatori și numerotare → Numerotare."}, "note": ""}, {"id": "III.4.b", "app": "html", "text": "Inserați o linie orizontală după primul paragraf al paginii web.", "pts": [[3, "Linie orizontală"], [2, "După primul paragraf"]], "sol": {"ms": "Word: Pornire → Borduri → Linie orizontală.", "lo": "Writer/Web: Inserare → Linie orizontală / stilul „Linie orizontală”."}, "note": ""}, {"id": "III.5.a", "app": "access", "text": "comp_a: Ștergeți din tabela comp_t înregistrarea corespunzătoare speciei pere.", "pts": [[3, "Înregistrare ștearsă"], [2, "Doar cea cu specia pere"]], "sol": {"ms": "Deschideți comp_t → selectați rândul (clic pe marginea din stânga) → Delete → Da.", "lo": "Base: clic dreapta pe antetul rândului → Șterge rândurile."}, "note": ""}, {"id": "III.5.b", "app": "access", "text": "Creați o interogare cu numele comp_p care afișează toate câmpurile din comp_t pentru speciile al căror nume începe cu litera p.", "pts": [[2, "Interogare comp_p"], [1, "Toate câmpurile"], [2, "Criteriul Like \"p*\""]], "sol": {"ms": "Proiectare interogare → comp_t.* → coloana Specia (debifată) → Criterii: Like \"p*\".", "lo": "Base: criteriu LIKE 'p*'."}, "note": ""}, {"id": "III.6.a", "app": "sistem", "text": "Ascundeți fișierul comp_d (atributul Ascuns / Hidden).", "pts": [[5, "Atribut Ascuns aplicat fișierului comp_d"]], "sol": {"ms": "Clic dreapta → Proprietăți → bifă Ascuns → OK.", "lo": "Linux: redenumire cu punct în față (.comp_d.txt)."}, "note": ""}, {"id": "III.6.b", "app": "sistem", "text": "Vizualizați conținutul directorului examen sub formă de detalii, sortat după tip. Salvați o captură a ferestrei la finalul fișierului comp_n.", "pts": [[1, "Captură"], [2, "Afișare detalii"], [2, "Sortare după tip"]], "sol": {"ms": "Vizualizare → Detalii; clic pe coloana Tip. Alt+PrtScn.", "lo": "Vizualizare listă, sortare după Tip."}, "note": ""}]}, {"id": "a7", "title": "Antrenament 7 – Sistemul solar", "theme": "Hermann Oberth · astronomie", "official": false, "kit": "resurse/kit_antrenament7.zip", "A": [{"id": "I.1.a", "app": "web", "text": "Căutați pe web anul nașterii pionierului rachetelor Hermann Oberth și anul în care a publicat lucrarea „Racheta în spațiul interplanetar”. Scrieți anii pe foaia de examen și salvați în directorul examen, ca pagină web numai HTML (HTML only), cu numele implicit, pagina/paginile folosite.", "pts": [[2, "Anii corecți (1894; 1923)"], [3, "Pagina salvată ca HTML only, nume implicit, în examen"]], "sol": {"ms": "Ctrl+S în browser → tip „Pagină web, numai HTML” → folderul examen → Salvare.", "lo": "Firefox: „Pagină web, doar HTML”; Chrome: „Pagină web, numai HTML”."}, "note": ""}, {"id": "I.1.b", "app": "web", "text": "Copiați în fișierul comp_n un paragraf despre contribuția lui Hermann Oberth la astronautică și o imagine cu o rachetă, precum și adresele paginilor web de pe care le-ați copiat.", "pts": [[2, "Paragraf"], [2, "Imagine"], [1, "Adresele paginilor"]], "sol": {"ms": "Copiere/lipire în comp_n, apoi URL-ul sub fiecare element. Salvați.", "lo": "Idem în LibreOffice Writer."}, "note": ""}], "B": [{"id": "II.1", "app": "teorie", "text": "Precizați rolul unui router într-o rețea.", "pts": [[5, "Rol corect precizat"]], "answer": "Routerul dirijează pachetele de date între rețele diferite, de exemplu între rețeaua locală și Internet; adesea oferă și conexiune Wi-Fi."}, {"id": "II.2", "app": "teorie", "text": "Explicați ce este stocarea în cloud și dați un exemplu de serviciu.", "pts": [[3, "Explicație"], [2, "Exemplu"]], "answer": "Păstrarea fișierelor pe servere accesate prin Internet, disponibile de pe orice dispozitiv. Exemple: Google Drive, OneDrive, Dropbox."}, {"id": "II.3", "app": "teorie", "text": "Precizați ce este rezoluția unui monitor și în ce unitate se exprimă.", "pts": [[3, "Definiție"], [2, "Unitate / exemplu"]], "answer": "Numărul de pixeli afișați pe orizontală × verticală, exprimat în pixeli (de ex. 1920×1080)."}, {"id": "III.1.a", "app": "word", "text": "comp_w: Scrieți în al treilea paragraf unitatea km cu exponent: după cuvântul kilometri adăugați textul (km2), cu cifra 2 ca exponent.", "pts": [[2, "Text adăugat"], [3, "Cifra 2 formatată ca exponent"]], "sol": {"ms": "Selectați 2 → Ctrl+Shift+= (Exponent).", "lo": "Format → Caracter → Poziție → Exponent (Ctrl+Shift+P)."}, "note": ""}, {"id": "III.1.b", "app": "word", "text": "Aplicați primului paragraf o bordură de tip casetă, cu linie albastră.", "pts": [[3, "Bordură casetă pe paragraf"], [2, "Culoare albastră"]], "sol": {"ms": "Pornire → Borduri → Borduri și umbrire → Casetă, culoare albastră, Se aplică la: Paragraf.", "lo": "Format → Paragraf → Borduri → toate laturile, culoare albastră."}, "note": ""}, {"id": "III.1.c", "app": "word", "text": "Transformați textul paragrafelor listei marcate în litere mari (MAJUSCULE).", "pts": [[3, "Majuscule aplicate"], [2, "Doar paragrafele listei marcate"]], "sol": {"ms": "Selectați → Pornire → Aa → MAJUSCULE (sau Shift+F3).", "lo": "Format → Text → MAJUSCULE."}, "note": ""}, {"id": "III.2.a", "app": "ppt", "text": "comp_p: Aplicați primului diapozitiv un fundal cu imaginea din fișierul comp_i.", "pts": [[3, "Fundal cu imagine"], [2, "Doar primul diapozitiv, fișierul comp_i"]], "sol": {"ms": "Clic dreapta → Formatare fundal → Umplere cu imagine sau textură → Inserare → comp_i.", "lo": "Diapozitiv → Proprietăți → Fundal → Bitmap → Adăugare/Import → comp_i → Nu pentru toate."}, "note": ""}, {"id": "III.2.b", "app": "ppt", "text": "Aplicați titlului din diapozitivul 2 o animație de intrare de tip Apariție (Appear), care să pornească după anteriorul (automat).", "pts": [[2, "Animație Apariție"], [3, "Pornire După anteriorul"]], "sol": {"ms": "Animații → Apariție → Pornire: După anteriorul.", "lo": "Format → Animație → Apariție → Pornire: După precedenta."}, "note": ""}, {"id": "III.2.c", "app": "ppt", "text": "Inserați în diapozitivul 3 un buton de acțiune (sau o formă) care, la clic, să ducă la primul diapozitiv.", "pts": [[3, "Buton / formă inserată"], [2, "Acțiune: primul diapozitiv"]], "sol": {"ms": "Inserare → Forme → Butoane de acțiune → Acasă → Hyperlink la: Primul diapozitiv.", "lo": "Desenați o formă → clic dreapta → Interacțiune → Salt la primul diapozitiv."}, "note": ""}, {"id": "III.3.a", "app": "excel", "text": "comp_x: Aplicați valorilor din C2:C9 formatul numeric cu o zecimală și separator de mii pentru B2:B9.", "pts": [[3, "C2:C9 cu o zecimală"], [2, "Separator de mii pe B2:B9"]], "sol": {"ms": "Ctrl+1 → Număr → Zecimale: 1; pentru B: bifă Utilizare separator mii.", "lo": "Format celule → Numere → Zecimale 1; Separator de mii."}, "note": ""}, {"id": "III.3.b", "app": "excel", "text": "Inserați în E2 o formulă care calculează raza planetei (diametrul împărțit la 2) și copiați-o până la E9.", "pts": [[3, "=B2/2"], [2, "Copiată E3:E9"]], "sol": {"ms": "E2: =B2/2 → ghidaj de umplere.", "lo": "Idem."}, "note": ""}, {"id": "III.3.c", "app": "excel", "text": "Inserați o diagramă de tip radială (pie) pe baza datelor A1:B5, cu etichete de date afișate ca procente.", "pts": [[2, "Diagramă radială"], [1, "Date A1:B5"], [2, "Etichete procentuale"]], "sol": {"ms": "Selectați A1:B5 → Inserare → Radială → Elemente diagramă → Etichete date → Procentaj.", "lo": "Inserare → Diagramă → Radială; Inserare etichete date → Afișează valoarea ca procent."}, "note": ""}, {"id": "III.4.a", "app": "html", "text": "comp_h: Aliniați la dreapta textul ultimului paragraf și aplicați-i dimensiunea fontului 18.", "pts": [[3, "Aliniere dreapta"], [2, "Dimensiune 18"]], "sol": {"ms": "Ctrl+R; dimensiune 18.", "lo": "Idem."}, "note": ""}, {"id": "III.4.b", "app": "html", "text": "Adăugați pe textul primului paragraf o legătură de tip e-mail către adresa observator@scoala.ro.", "pts": [[3, "Legătură e-mail (mailto:)"], [2, "Adresa corectă"]], "sol": {"ms": "Ctrl+K → Adresă de e-mail.", "lo": "Ctrl+K → E-mail → Destinatar."}, "note": ""}, {"id": "III.5.a", "app": "access", "text": "comp_a: Stabiliți pentru câmpul Glucoză din tabela comp_t legenda (Caption) Glucoză (g/100 g).", "pts": [[3, "Proprietatea Legendă modificată"], [2, "Textul corect"]], "sol": {"ms": "comp_t → Vizualizare proiect → Glucoză → Proprietăți: Legendă → Salvare.", "lo": "Base nu are legendă de câmp – exercițiul se face în Access."}, "note": ""}, {"id": "III.5.b", "app": "access", "text": "Creați o interogare de totaluri cu numele comp_tot care afișează, pentru fiecare magazin, numărul de specii.", "pts": [[2, "Interogare comp_tot"], [1, "Grupare după Magazin"], [2, "Numărare (Count) pe Specia"]], "sol": {"ms": "Proiectare interogare → Magazin, Specia → Totaluri (Σ) → Magazin: Grupare după, Specia: Numărare.", "lo": "Base: Funcție: Grupare / Numărare."}, "note": ""}, {"id": "III.6.a", "app": "sistem", "text": "Copiați directorul examen (cu tot conținutul) pe Desktop, cu numele examen_copie.", "pts": [[3, "Director copiat"], [2, "Nume examen_copie, pe Desktop"]], "sol": {"ms": "Ctrl+C pe folder → Desktop → Ctrl+V → F2.", "lo": "Idem."}, "note": ""}, {"id": "III.6.b", "app": "sistem", "text": "Afișați extensiile fișierelor în managerul de fișiere și salvați o captură a ferestrei directorului examen la finalul fișierului comp_w.", "pts": [[1, "Captură"], [4, "Extensiile vizibile în fereastra examen"]], "sol": {"ms": "Vizualizare → Afișare → Extensii nume fișier. Alt+PrtScn.", "lo": "Linux: extensiile sunt afișate implicit."}, "note": ""}]}, {"id": "a8", "title": "Antrenament 8 – Munții Carpați", "theme": "George Enescu · geografie", "official": false, "kit": "resurse/kit_antrenament8.zip", "A": [{"id": "I.1.a", "app": "web", "text": "Căutați pe web anul nașterii compozitorului George Enescu și anul în care a compus Rapsodia română nr. 1. Scrieți anii pe foaia de examen și salvați în directorul examen, ca pagină web numai HTML (HTML only), cu numele implicit, pagina/paginile folosite.", "pts": [[2, "Anii corecți (1881; 1901)"], [3, "Pagina salvată ca HTML only, nume implicit, în examen"]], "sol": {"ms": "Ctrl+S în browser → tip „Pagină web, numai HTML” → folderul examen → Salvare.", "lo": "Firefox: „Pagină web, doar HTML”; Chrome: „Pagină web, numai HTML”."}, "note": ""}, {"id": "I.1.b", "app": "web", "text": "Copiați în fișierul comp_n un paragraf despre Festivalul „George Enescu” și o imagine cu vioara sau portretul compozitorului, precum și adresele paginilor web de pe care le-ați copiat.", "pts": [[2, "Paragraf"], [2, "Imagine"], [1, "Adresele paginilor"]], "sol": {"ms": "Copiere/lipire în comp_n, apoi URL-ul sub fiecare element. Salvați.", "lo": "Idem în LibreOffice Writer."}, "note": ""}], "B": [{"id": "II.1", "app": "teorie", "text": "Explicați diferența dintre copierea și mutarea unui fișier.", "pts": [[3, "Copiere"], [2, "Mutare"]], "answer": "La copiere fișierul rămâne în locația inițială și apare o dublură în cea nouă; la mutare fișierul dispare din locația inițială și există doar în cea nouă."}, {"id": "II.2", "app": "teorie", "text": "Precizați ce este spam-ul și o măsură de protecție.", "pts": [[3, "Definiție"], [2, "Măsură"]], "answer": "Mesaje nesolicitate trimise în masă (reclame, fraude). Protecție: filtrul anti-spam, nu se răspunde, nu se dau clic pe linkuri, adresa nu se publică pe site-uri."}, {"id": "II.3", "app": "teorie", "text": "Precizați rolul Coșului de reciclare.", "pts": [[5, "Rol corect"]], "answer": "Păstrează temporar fișierele șterse de pe disc, care pot fi restaurate; golirea lui le șterge definitiv."}, {"id": "III.1.a", "app": "word", "text": "comp_w: Stabiliți pentru document dimensiunea paginii A5 și marginile de 1,5 cm pe toate laturile.", "pts": [[2, "Dimensiune A5"], [3, "Margini 1,5 cm (toate)"]], "sol": {"ms": "Aspect → Dimensiune → A5; Margini particularizate 1,5 cm.", "lo": "Format → Stil pagină → Pagină → Format A5; margini 1,5 cm."}, "note": ""}, {"id": "III.1.b", "app": "word", "text": "Inserați după ultimul paragraf imaginea comp_i, cu lățimea de 8 cm și încadrarea în text de tip Pătrat (Square).", "pts": [[2, "Imagine inserată"], [2, "Lățime 8 cm"], [1, "Încadrare Pătrat"]], "sol": {"ms": "Inserare → Imagini → comp_i; Format imagine → Lățime 8 cm; Încadrare text → Pătrat.", "lo": "Inserare → Imagine; Format → Imagine → Poziție și dimensiune; Încadrare → Paginare (Pagină)."}, "note": ""}, {"id": "III.1.c", "app": "word", "text": "Inserați în subsolul documentului data curentă, actualizată automat.", "pts": [[3, "Dată în subsol"], [2, "Câmp actualizat automat"]], "sol": {"ms": "Inserare → Subsol → Inserare → Dată și oră → bifă Actualizare automată.", "lo": "Inserare → Antet și subsol → Subsol; Inserare → Câmp → Dată (variabilă)."}, "note": ""}, {"id": "III.2.a", "app": "ppt", "text": "comp_p: Inserați în diapozitivul 2 o notă a vorbitorului cu textul Cel mai înalt vârf din România.", "pts": [[3, "Notă inserată"], [2, "Pe diapozitivul 2, text corect"]], "sol": {"ms": "Clic în panoul Note de sub diapozitiv → scrieți.", "lo": "Vizualizare → Note → scrieți textul."}, "note": ""}, {"id": "III.2.b", "app": "ppt", "text": "Aplicați imaginii din diapozitivul 2 un efect de animație pe traseu (motion path) de tip linie.", "pts": [[3, "Animație pe traseu"], [2, "Tip linie, pe imagine"]], "sol": {"ms": "Animații → Trasee de mișcare → Linii.", "lo": "Format → Animație → + → Trasee de mișcare → Linie."}, "note": ""}, {"id": "III.2.c", "app": "ppt", "text": "Modificați dimensiunea diapozitivelor la formatul 4:3 (standard).", "pts": [[5, "Format 4:3"]], "sol": {"ms": "Proiectare → Dimensiune diapozitiv → Standard (4:3).", "lo": "Diapozitiv → Proprietăți diapozitiv → Diapozitiv → Format: Ecran 4:3."}, "note": ""}, {"id": "III.3.a", "app": "excel", "text": "comp_x: Sortați datele A1:D9 după Grupă crescător și, pentru aceeași grupă, după Altitudine descrescător.", "pts": [[2, "Sortare cu două criterii"], [3, "Grupă crescător + Altitudine descrescător"]], "sol": {"ms": "Date → Sortare → Adăugare nivel.", "lo": "Date → Sortare → Cheie 1, Cheie 2."}, "note": ""}, {"id": "III.3.b", "app": "excel", "text": "Inserați în E2 o formulă care calculează diferența dintre altitudinea vârfului și altitudinea Vârfului Moldoveanu (B2), folosind referință absolută. Copiați formula până la E9.", "pts": [[3, "=B2-$B$2 (referință absolută)"], [2, "Copiată E3:E9"]], "sol": {"ms": "E2: =B2-$B$2 (F4 pentru $) → copiere.", "lo": "Idem (F4 alternează referințele)."}, "note": ""}, {"id": "III.3.c", "app": "excel", "text": "Adăugați celulei B2 un comentariu (notă) cu textul cel mai înalt vârf și ascundeți coloana D.", "pts": [[3, "Comentariu/notă pe B2"], [2, "Coloana D ascunsă"]], "sol": {"ms": "Clic dreapta pe B2 → Notă nouă; clic dreapta pe D → Ascundere.", "lo": "Inserare → Comentariu; clic dreapta pe coloană → Ascunde coloanele."}, "note": ""}, {"id": "III.4.a", "app": "html", "text": "comp_h: Transformați primul paragraf într-un titlu de nivel 2 (Heading 2) și colorați-l albastru.", "pts": [[3, "Titlu 2"], [2, "Culoare albastră"]], "sol": {"ms": "Stiluri → Titlu 2; culoare font albastru.", "lo": "Stil Titlu 2 (Ctrl+2); culoare albastră."}, "note": ""}, {"id": "III.4.b", "app": "html", "text": "Inserați după ultimul paragraf imaginea comp_i și adăugați pe imagine o legătură către fișierul comp_w.", "pts": [[2, "Imagine inserată"], [3, "Legătură pe imagine către comp_w"]], "sol": {"ms": "Inserare imagine → selectați imaginea → Ctrl+K → comp_w.docx.", "lo": "Inserare imagine → Ctrl+K → Document → comp_w.docx."}, "note": ""}, {"id": "III.5.a", "app": "access", "text": "comp_a: Redenumiți câmpul Magazin din tabela comp_t în Punct_vanzare.", "pts": [[5, "Câmp redenumit corect"]], "sol": {"ms": "comp_t → Vizualizare proiect → Nume câmp: Punct_vanzare → Salvare.", "lo": "Base: Editare tabel → redenumire câmp (tabela să nu fie deschisă)."}, "note": ""}, {"id": "III.5.b", "app": "access", "text": "Creați o interogare cu numele comp_b care afișează Specia și Glucoză pentru valorile Glucoză cuprinse între 2 și 3, sortate crescător după Glucoză.", "pts": [[2, "Interogare comp_b"], [2, "Criteriul Between 2 And 3"], [1, "Sortare crescătoare"]], "sol": {"ms": "Criterii: Between 2 And 3; Sortare: Ascendent.", "lo": "Base: criteriu BETWEEN 2 AND 3."}, "note": ""}, {"id": "III.6.a", "app": "sistem", "text": "Creați în directorul examen două subdirectoare, texte și imagini, și mutați comp_w în texte, respectiv comp_i în imagini.", "pts": [[2, "Cele două subdirectoare"], [3, "Fișierele mutate corect"]], "sol": {"ms": "Nou → Folder; Ctrl+X / Ctrl+V.", "lo": "Idem."}, "note": ""}, {"id": "III.6.b", "app": "sistem", "text": "Vizualizați conținutul directorului examen sub formă de dale (Tiles) și salvați o captură a ferestrei la finalul fișierului comp_n.", "pts": [[1, "Captură"], [4, "Fereastra examen, afișare Dale"]], "sol": {"ms": "Vizualizare → Dale. Alt+PrtScn.", "lo": "Vizualizare pictograme."}, "note": ""}]}, {"id": "a9", "title": "Antrenament 9 – Fotosinteza", "theme": "Emil Racoviță · biologie", "official": false, "kit": "resurse/kit_antrenament9.zip", "A": [{"id": "I.1.a", "app": "web", "text": "Căutați pe web anul nașterii savantului Emil Racoviță și anul în care a pornit expediția antarctică Belgica. Scrieți anii pe foaia de examen și salvați în directorul examen, ca pagină web numai HTML (HTML only), cu numele implicit, pagina/paginile folosite.", "pts": [[2, "Anii corecți (1868; 1897)"], [3, "Pagina salvată ca HTML only, nume implicit, în examen"]], "sol": {"ms": "Ctrl+S în browser → tip „Pagină web, numai HTML” → folderul examen → Salvare.", "lo": "Firefox: „Pagină web, doar HTML”; Chrome: „Pagină web, numai HTML”."}, "note": ""}, {"id": "I.1.b", "app": "web", "text": "Copiați în fișierul comp_n un paragraf despre biospeologie și o imagine cu nava Belgica, precum și adresele paginilor web de pe care le-ați copiat.", "pts": [[2, "Paragraf"], [2, "Imagine"], [1, "Adresele paginilor"]], "sol": {"ms": "Copiere/lipire în comp_n, apoi URL-ul sub fiecare element. Salvați.", "lo": "Idem în LibreOffice Writer."}, "note": ""}], "B": [{"id": "II.1", "app": "teorie", "text": "Explicați ce înseamnă software open source și dați un exemplu.", "pts": [[3, "Explicație"], [2, "Exemplu"]], "answer": "Software al cărui cod sursă este public și poate fi studiat, modificat și redistribuit. Exemple: LibreOffice, Linux, Firefox."}, {"id": "II.2", "app": "teorie", "text": "Ce este un cal troian (troian)? Precizați o măsură de protecție.", "pts": [[3, "Definiție"], [2, "Măsură"]], "answer": "Program malițios deghizat într-o aplicație utilă, care fură date sau oferă acces neautorizat. Protecție: descărcare doar din surse sigure, antivirus actualizat."}, {"id": "II.3", "app": "teorie", "text": "Precizați diferența dintre tastele PrtScn și combinația Alt+PrtScn.", "pts": [[3, "PrtScn"], [2, "Alt+PrtScn"]], "answer": "PrtScn copiază imaginea întregului ecran; Alt+PrtScn copiază doar fereastra activă."}, {"id": "III.1.a", "app": "word", "text": "comp_w: Aplicați primului paragraf stilul Titlu 1 (Heading 1), iar paragrafelor „Factori care influențează fotosinteza:” și „Produsele fotosintezei:” stilul Titlu 2.", "pts": [[2, "Titlu 1 pe primul paragraf"], [3, "Titlu 2 pe cele două paragrafe"]], "sol": {"ms": "Pornire → Stiluri → Titlu 1 / Titlu 2.", "lo": "Stiluri → Titlu 1 (Ctrl+1) / Titlu 2 (Ctrl+2)."}, "note": ""}, {"id": "III.1.b", "app": "word", "text": "Inserați la începutul documentului un cuprins automat, generat pe baza titlurilor.", "pts": [[3, "Cuprins automat"], [2, "La începutul documentului"]], "sol": {"ms": "Ctrl+Home → Referințe → Cuprins → Tabel automat.", "lo": "Inserare → Cuprins și index → Cuprins, index sau bibliografie."}, "note": ""}, {"id": "III.1.c", "app": "word", "text": "Stabiliți pentru paragrafele listei numerotate spațierea înainte de 12 pt și interlinia dublă.", "pts": [[2, "Spațiere înainte 12 pt"], [3, "Interlinie dublă"]], "sol": {"ms": "Paragraf → Înainte: 12 pt; Spațiere rânduri: Dublu.", "lo": "Format → Paragraf → Deasupra paragrafului 12 pt; Interlinie: Dublă."}, "note": ""}, {"id": "III.2.a", "app": "ppt", "text": "comp_p: Inserați în diapozitivul 3 o diagramă de tip coloană (cu datele implicite).", "pts": [[3, "Diagramă inserată"], [2, "Tip coloană, pe diapozitivul 3"]], "sol": {"ms": "Inserare → Diagramă → Coloană.", "lo": "Inserare → Diagramă (implicit coloane)."}, "note": ""}, {"id": "III.2.b", "app": "ppt", "text": "Desenați în diapozitivul 2 un cerc și un dreptunghi și grupați-le într-un singur obiect.", "pts": [[2, "Cele două forme desenate"], [3, "Forme grupate"]], "sol": {"ms": "Inserare → Forme → cerc, dreptunghi; selectați-le (Shift) → clic dreapta → Grupare.", "lo": "Selectați formele → Format → Grupare → Grupare (Ctrl+Shift+G)."}, "note": ""}, {"id": "III.2.c", "app": "ppt", "text": "Mutați al treilea diapozitiv pe prima poziție în prezentare.", "pts": [[5, "Ordinea modificată corect"]], "sol": {"ms": "Trageți miniatura în partea de sus.", "lo": "Trageți în panoul Diapozitive sau Diapozitiv → Mutare → Diapozitivul la început."}, "note": ""}, {"id": "III.3.a", "app": "excel", "text": "comp_x: Aplicați celulelor B2:B9 o formatare condiționată care colorează cu roșu textul valorilor mai mici decât 10.", "pts": [[2, "Formatare condiționată"], [3, "Condiția < 10, text roșu"]], "sol": {"ms": "Formatare condiționată → Mai mic decât → 10 → Text roșu.", "lo": "Format → Condițional → Condiție: < 10 → stil cu font roșu."}, "note": ""}, {"id": "III.3.b", "app": "excel", "text": "Inserați în B10 o formulă care calculează media valorilor din B2:B9, rotunjită la o zecimală.", "pts": [[3, "ROUND + AVERAGE"], [2, "Rezultat pe B2:B9 cu o zecimală"]], "sol": {"ms": "B10: =ROUND(AVERAGE(B2:B9),1).", "lo": "B10: =ROUND(AVERAGE(B2:B9);1)."}, "note": ""}, {"id": "III.3.c", "app": "excel", "text": "Inserați o diagramă de tip linie care să arate variația numărului de bule (B2:B9) în funcție de distanță (A2:A9), cu titlul Intensitatea fotosintezei.", "pts": [[2, "Diagramă linie"], [2, "Seriile corecte"], [1, "Titlul"]], "sol": {"ms": "Selectați A1:B9 → Inserare → Linie (dacă distanța apare ca serie, folosiți Dispersie cu linii).", "lo": "Inserare → Diagramă → Linie / XY (Dispersie); Prima coloană ca etichetă."}, "note": ""}, {"id": "III.4.a", "app": "html", "text": "comp_h: Aplicați textului întregii pagini fontul Courier New (sau Liberation Mono) și culoarea verde închis.", "pts": [[3, "Font"], [2, "Culoare verde închis"]], "sol": {"ms": "Ctrl+A → font Courier New → culoare verde închis.", "lo": "Ctrl+A → Liberation Mono → culoare."}, "note": ""}, {"id": "III.4.b", "app": "html", "text": "Inserați după ultimul paragraf un tabel cu 3 rânduri și 2 coloane, cu bordură.", "pts": [[3, "Tabel 3×2"], [2, "Bordură vizibilă"]], "sol": {"ms": "Inserare → Tabel 2×3 → Proiectare tabel → Toate bordurile.", "lo": "Ctrl+F12 → 2 coloane, 3 rânduri; Borduri."}, "note": ""}, {"id": "III.5.a", "app": "access", "text": "comp_a: Stabiliți pentru câmpul Glucoză o regulă de validare care acceptă doar valori mai mari sau egale cu 0 și textul de validare Valoare invalidă.", "pts": [[3, "Regulă de validare >=0"], [2, "Text de validare"]], "sol": {"ms": "Vizualizare proiect → Glucoză → Regulă de validare: >=0; Text de validare: Valoare invalidă.", "lo": "Exercițiul se face în Access."}, "note": ""}, {"id": "III.5.b", "app": "access", "text": "Creați un formular cu numele comp_fc, cu aspect pe coloane (columnar), care să conțină câmpurile Specia, Glucoză și Fructoză, și cu titlul Fructe.", "pts": [[2, "Formular comp_fc"], [1, "Câmpurile cerute"], [1, "Aspect coloane"], [1, "Titlul Fructe"]], "sol": {"ms": "Expert formular → câmpuri → Coloană → titlu: Fructe → salvare comp_fc.", "lo": "Base: Expert formulare → Coloane – etichete stânga."}, "note": ""}, {"id": "III.6.a", "app": "sistem", "text": "Creați în directorul examen un document text nou, cu numele observatii.txt, care să conțină textul fotosinteza.", "pts": [[3, "Fișier observatii.txt"], [2, "Conținutul corect"]], "sol": {"ms": "Clic dreapta → Nou → Document text → scrieți în Notepad → Salvare.", "lo": "Clic dreapta → Document nou → Document gol; editați cu editorul de text."}, "note": ""}, {"id": "III.6.b", "app": "sistem", "text": "Deschideți fereastra Proprietăți a directorului examen, în care să fie vizibilă dimensiunea lui, și salvați o captură la finalul fișierului comp_n.", "pts": [[1, "Captură"], [4, "Fereastra Proprietăți a directorului examen"]], "sol": {"ms": "Clic dreapta pe examen → Proprietăți → Alt+PrtScn.", "lo": "Idem."}, "note": ""}]}, {"id": "a10", "title": "Antrenament 10 – Revoluția de la 1848", "theme": "Aurel Vlaicu · istorie", "official": false, "kit": "resurse/kit_antrenament10.zip", "A": [{"id": "I.1.a", "app": "web", "text": "Căutați pe web anul nașterii inginerului Aurel Vlaicu și anul primului zbor cu avionul Vlaicu I. Scrieți anii pe foaia de examen și salvați în directorul examen, ca pagină web numai HTML (HTML only), cu numele implicit, pagina/paginile folosite.", "pts": [[2, "Anii corecți (1882; 1910)"], [3, "Pagina salvată ca HTML only, nume implicit, în examen"]], "sol": {"ms": "Ctrl+S în browser → tip „Pagină web, numai HTML” → folderul examen → Salvare.", "lo": "Firefox: „Pagină web, doar HTML”; Chrome: „Pagină web, numai HTML”."}, "note": ""}, {"id": "I.1.b", "app": "web", "text": "Copiați în fișierul comp_n un paragraf despre avionul Vlaicu II și o imagine cu Aurel Vlaicu sau cu avionul său, precum și adresele paginilor web de pe care le-ați copiat.", "pts": [[2, "Paragraf"], [2, "Imagine"], [1, "Adresele paginilor"]], "sol": {"ms": "Copiere/lipire în comp_n, apoi URL-ul sub fiecare element. Salvați.", "lo": "Idem în LibreOffice Writer."}, "note": ""}], "B": [{"id": "II.1", "app": "teorie", "text": "Precizați două componente ale unei adrese de e-mail.", "pts": [[3, "Prima componentă"], [2, "A doua componentă"]], "answer": "Numele utilizatorului, simbolul @ și domeniul (serverul): elev@scoala.ro."}, {"id": "II.2", "app": "teorie", "text": "Explicați de ce este importantă realizarea copiilor de siguranță (backup).", "pts": [[5, "Explicație corectă"]], "answer": "Permit recuperarea datelor în caz de defectare a dispozitivului, ștergere accidentală, furt sau atac ransomware."}, {"id": "II.3", "app": "teorie", "text": "Ce este o comandă rapidă (shortcut) pe Desktop? Ce se întâmplă cu fișierul original dacă ștergem comanda rapidă?", "pts": [[3, "Definiție"], [2, "Efectul ștergerii"]], "answer": "Un fișier mic care indică spre alt fișier/program și îl deschide rapid. Ștergerea comenzii rapide nu afectează fișierul original."}, {"id": "III.1.a", "app": "word", "text": "comp_w: Inserați după primul paragraf un tabel cu 2 coloane și 3 rânduri și scrieți în primul rând Provincie și Eveniment.", "pts": [[3, "Tabel 2×3 după primul paragraf"], [2, "Antetul corect"]], "sol": {"ms": "Cursor după paragraful 1 → Enter → Inserare → Tabel 2×3.", "lo": "Tabel → Inserare tabel → 2×3."}, "note": ""}, {"id": "III.1.b", "app": "word", "text": "Aplicați celui de-al doilea paragraf o umbrire gri deschis și o bordură de sus și de jos.", "pts": [[2, "Umbrire gri deschis"], [3, "Borduri sus și jos"]], "sol": {"ms": "Pornire → Umbrire → gri; Borduri → Bordură sus / Bordură jos.", "lo": "Format → Paragraf → Zonă → gri; Borduri → sus și jos."}, "note": ""}, {"id": "III.1.c", "app": "word", "text": "Inserați o notă de final pe cuvântul Blaj din ultimul paragraf, cu textul oraș din județul Alba.", "pts": [[3, "Notă de final"], [2, "Pe cuvântul Blaj, textul cerut"]], "sol": {"ms": "Referințe → Inserare notă de final.", "lo": "Inserare → Notă de subsol și notă de final → Notă de final."}, "note": ""}, {"id": "III.2.a", "app": "ppt", "text": "comp_p: Inserați la finalul prezentării un diapozitiv nou, cu aspectul Titlu și conținut, care să aibă titlul Bibliografie.", "pts": [[2, "Diapozitiv la final"], [2, "Aspect Titlu și conținut"], [1, "Titlul"]], "sol": {"ms": "Selectați ultimul → Diapozitiv nou → Titlu și conținut.", "lo": "Diapozitiv nou → aspect Titlu, conținut."}, "note": ""}, {"id": "III.2.b", "app": "ppt", "text": "Aplicați textului din diapozitivul 2 o animație de intrare de tip Estompare (Fade), în care rândurile să apară pe rând, la clic.", "pts": [[2, "Animație Estompare"], [3, "Pe paragrafe, la clic"]], "sol": {"ms": "Animații → Estompare → Opțiuni efect → După paragraf.", "lo": "Format → Animație → Estompare; Opțiuni text: După paragraf."}, "note": ""}, {"id": "III.2.c", "app": "ppt", "text": "Inserați în subsolul tuturor diapozitivelor textul Istorie 2026.", "pts": [[3, "Subsol cu textul"], [2, "Pe toate diapozitivele"]], "sol": {"ms": "Inserare → Antet și subsol → Subsol → Se aplică la toate.", "lo": "Inserare → Antet și subsol → Subsol → Aplică tuturor."}, "note": ""}, {"id": "III.3.a", "app": "excel", "text": "comp_x: Îmbinați celulele E1:F1, scrieți în ele textul Observații și aplicați bordură groasă în jurul lor.", "pts": [[2, "Îmbinare E1:F1"], [1, "Textul"], [2, "Bordură groasă exterioară"]], "sol": {"ms": "Îmbinare și centrare; Borduri → Bordură groasă tip casetă.", "lo": "Format → Îmbinare celule; Format celule → Borduri → linie groasă."}, "note": ""}, {"id": "III.3.b", "app": "excel", "text": "Inserați în D10 o formulă care calculează suma participanților din D2:D9, iar în D11 numărul evenimentelor din Moldova (coloana C).", "pts": [[3, "D10: =SUM(D2:D9)"], [2, "D11: =COUNTIF(C2:C9,\"Moldova\")"]], "sol": {"ms": "D10: =SUM(D2:D9); D11: =COUNTIF(C2:C9,\"Moldova\").", "lo": "Idem, cu ; ca separator."}, "note": ""}, {"id": "III.3.c", "app": "excel", "text": "Aplicați celulelor A2:A9 alinierea verticală centrată și orientarea textului la 45°.", "pts": [[2, "Aliniere verticală centrată"], [3, "Orientare 45°"]], "sol": {"ms": "Ctrl+1 → Aliniere → Verticală: Centru; Orientare 45.", "lo": "Format celule → Aliniere → Verticală: Mijloc; Grade: 45."}, "note": ""}, {"id": "III.4.a", "app": "html", "text": "comp_h: Aplicați textului celui de-al doilea paragraf culoarea de fundal (evidențiere) galben.", "pts": [[3, "Evidențiere / fundal aplicat"], [2, "Culoare galbenă, paragraful 2"]], "sol": {"ms": "Culoare evidențiere text → Galben.", "lo": "Format → Caracter → Evidențiere → Galben."}, "note": ""}, {"id": "III.4.b", "app": "html", "text": "Adăugați pe textul ultimului paragraf o legătură către fișierul comp_p.", "pts": [[3, "Legătură"], [2, "Către comp_p, ultimul paragraf"]], "sol": {"ms": "Ctrl+K → comp_p.pptx.", "lo": "Ctrl+K → Document → comp_p.pptx."}, "note": ""}, {"id": "III.5.a", "app": "access", "text": "comp_a: Adăugați în tabela comp_t câmpul Data_aprov, de tip Dată/Oră, cu formatul Dată scurtă.", "pts": [[2, "Câmp adăugat"], [2, "Tip Dată/Oră"], [1, "Format Dată scurtă"]], "sol": {"ms": "Vizualizare proiect → Data_aprov, Dată/Oră → Format: Dată scurtă.", "lo": "Base: tip Dată; format DD.MM.YY."}, "note": ""}, {"id": "III.5.b", "app": "access", "text": "Creați o interogare cu numele comp_s care afișează câmpurile Specia și Magazin pentru înregistrările care nu au valoare în câmpul Fructoză.", "pts": [[2, "Interogare comp_s"], [1, "Câmpurile cerute"], [2, "Criteriul Is Null pe Fructoză"]], "sol": {"ms": "Criterii la Fructoză (neafișat): Is Null.", "lo": "Base: criteriu IS EMPTY / IS NULL."}, "note": ""}, {"id": "III.6.a", "app": "sistem", "text": "În directorul examen creați o arhivă cu numele istorie48 care să conțină toate fișierele de tip .docx din director.", "pts": [[3, "Arhivă istorie48"], [2, "Conține fișierele .docx"]], "sol": {"ms": "Selectați comp_w și comp_n → Trimitere la → Folder comprimat → istorie48.", "lo": "Comprimare… → istorie48.zip."}, "note": ""}, {"id": "III.6.b", "app": "sistem", "text": "Ștergeți fișierul comp_d, apoi deschideți Coșul de reciclare și salvați o captură a ferestrei în care se vede fișierul șters, la finalul fișierului comp_n.", "pts": [[1, "Captură"], [4, "Fereastra Coșului cu fișierul comp_d"]], "sol": {"ms": "Delete → dublu-clic pe Coș de reciclare → Alt+PrtScn.", "lo": "Coș de gunoi în managerul de fișiere."}, "note": ""}]}, {"id": "a11", "title": "Antrenament 11 – Educație financiară", "theme": "Traian Vuia · bugetul personal", "official": false, "kit": "resurse/kit_antrenament11.zip", "A": [{"id": "I.1.a", "app": "web", "text": "Căutați pe web anul nașterii inventatorului Traian Vuia și anul în care a realizat primul zbor cu aparatul său. Scrieți anii pe foaia de examen și salvați în directorul examen, ca pagină web numai HTML (HTML only), cu numele implicit, pagina/paginile folosite.", "pts": [[2, "Anii corecți (1872; 1906)"], [3, "Pagina salvată ca HTML only, nume implicit, în examen"]], "sol": {"ms": "Ctrl+S în browser → tip „Pagină web, numai HTML” → folderul examen → Salvare.", "lo": "Firefox: „Pagină web, doar HTML”; Chrome: „Pagină web, numai HTML”."}, "note": ""}, {"id": "I.1.b", "app": "web", "text": "Copiați în fișierul comp_n un paragraf despre aparatul de zbor Vuia I și o imagine cu Traian Vuia sau cu aparatul, precum și adresele paginilor web de pe care le-ați copiat.", "pts": [[2, "Paragraf"], [2, "Imagine"], [1, "Adresele paginilor"]], "sol": {"ms": "Copiere/lipire în comp_n, apoi URL-ul sub fiecare element. Salvați.", "lo": "Idem în LibreOffice Writer."}, "note": ""}], "B": [{"id": "II.1", "app": "teorie", "text": "Precizați diferența dintre freeware și shareware.", "pts": [[3, "Freeware"], [2, "Shareware"]], "answer": "Freeware: gratuit, fără limită de timp. Shareware: gratuit o perioadă de probă sau cu funcții limitate, apoi trebuie cumpărat."}, {"id": "II.2", "app": "teorie", "text": "Explicați ce este autentificarea în doi pași (2FA) și de ce este utilă.", "pts": [[3, "Explicație"], [2, "Utilitate"]], "answer": "Pe lângă parolă, se cere o a doua confirmare (cod SMS, aplicație). Contul rămâne protejat chiar dacă parola a fost furată."}, {"id": "II.3", "app": "teorie", "text": "Ce indică prefixul https:// din adresa unui site de plăți?", "pts": [[5, "Răspuns corect"]], "answer": "Conexiune securizată, criptată, între browser și server; datele (de ex. cele ale cardului) nu pot fi citite ușor de alții."}, {"id": "III.1.a", "app": "word", "text": "comp_w: Inserați la sfârșitul documentului simbolul © urmat de textul Club de economie 2026.", "pts": [[3, "Simbolul ©"], [2, "Textul, la final"]], "sol": {"ms": "Ctrl+End → Inserare → Simbol → ©.", "lo": "Inserare → Caracter special → ©."}, "note": ""}, {"id": "III.1.b", "app": "word", "text": "Inserați pe cuvintele Bugetul personal de la începutul celui de-al doilea paragraf o legătură către adresa https://www.bnr.ro.", "pts": [[3, "Hyperlink"], [2, "Pe textul și adresa corecte"]], "sol": {"ms": "Selectați → Ctrl+K → Adresă.", "lo": "Ctrl+K → Internet → URL."}, "note": ""}, {"id": "III.1.c", "app": "word", "text": "Inserați înaintea primului paragraf o casetă text cu textul Bugetul meu, cu fundal verde deschis.", "pts": [[3, "Casetă text inserată"], [2, "Text și fundal verde deschis"]], "sol": {"ms": "Inserare → Casetă text → Desenare → Format formă → Umplere.", "lo": "Inserare → Casetă text → Format → Zonă → Culoare."}, "note": ""}, {"id": "III.2.a", "app": "ppt", "text": "comp_p: Schimbați ordinea obiectelor din diapozitivul 1 astfel încât titlul să fie adus în prim-plan și aplicați-i culoarea verde.", "pts": [[2, "Titlu adus în prim-plan"], [3, "Culoare verde a textului"]], "sol": {"ms": "Clic dreapta pe titlu → Aducere în prim-plan; culoare font verde.", "lo": "Format → Aranjare → Adu în față; Format → Caracter → culoare."}, "note": ""}, {"id": "III.2.b", "app": "ppt", "text": "Transformați textul din diapozitivul 3 într-o reprezentare SmartArt de tip listă (sau într-o listă numerotată, în Impress).", "pts": [[3, "Conversie realizată"], [2, "Conținutul păstrat"]], "sol": {"ms": "Selectați caseta → Pornire → Conversie în SmartArt → listă.", "lo": "Impress: Format → Marcatori și numerotare → Numerotare."}, "note": ""}, {"id": "III.2.c", "app": "ppt", "text": "Configurați expunerea astfel încât să ruleze în buclă continuă până la apăsarea tastei Esc.", "pts": [[5, "Buclă continuă activată"]], "sol": {"ms": "Expunere diapozitive → Configurare expunere → Buclă continuă până la Esc.", "lo": "Expunere → Setări expunere → Buclă și repetă după."}, "note": ""}, {"id": "III.3.a", "app": "excel", "text": "comp_x: Aplicați valorilor din B2:D9 formatul monedă cu simbolul lei și două zecimale.", "pts": [[3, "Format monedă"], [2, "Lei, două zecimale, B2:D9"]], "sol": {"ms": "Ctrl+1 → Monedă → Simbol: lei → 2 zecimale.", "lo": "Format celule → Monedă → RON/lei."}, "note": ""}, {"id": "III.3.b", "app": "excel", "text": "Inserați în E1 textul Total și în E2 o formulă care calculează totalul cheltuielilor pe trei luni pentru categoria din rândul 2. Copiați formula până la E9.", "pts": [[3, "=SUM(B2:D2)"], [2, "Antet și copiere E3:E9"]], "sol": {"ms": "E2: =SUM(B2:D2) → ghidaj.", "lo": "Idem."}, "note": ""}, {"id": "III.3.c", "app": "excel", "text": "Aplicați validarea datelor pentru B2:D9 astfel încât să se accepte doar numere întregi între 0 și 1000.", "pts": [[2, "Validare aplicată pe B2:D9"], [3, "Număr întreg între 0 și 1000"]], "sol": {"ms": "Date → Validare date → Număr întreg → între 0 și 1000.", "lo": "Date → Validitate → Număr întreg → între 0 și 1000."}, "note": ""}, {"id": "III.4.a", "app": "html", "text": "comp_h: Aplicați titlului paginii (elementul title) textul Clubul de economie și primului paragraf stilul aldin.", "pts": [[3, "Titlul paginii"], [2, "Primul paragraf aldin"]], "sol": {"ms": "Fișier → Informații → Proprietăți → Titlu; Ctrl+B.", "lo": "Fișier → Proprietăți → Descriere → Titlu; Ctrl+B."}, "note": ""}, {"id": "III.4.b", "app": "html", "text": "Transformați paragrafele 2 și 3 într-o listă marcată.", "pts": [[3, "Listă marcată"], [2, "Paragrafele 2 și 3"]], "sol": {"ms": "Selectați → Marcatori.", "lo": "Format → Marcatori și numerotare."}, "note": ""}, {"id": "III.5.a", "app": "access", "text": "comp_a: Stabiliți pentru câmpul Magazin valoarea implicită Magazin 1 și faceți câmpul obligatoriu (Required).", "pts": [[3, "Valoare implicită"], [2, "Câmp obligatoriu"]], "sol": {"ms": "Vizualizare proiect → Magazin → Valoare implicită: \"Magazin 1\"; Obligatoriu: Da.", "lo": "Base: Valoare implicită; Intrare necesară: Da."}, "note": ""}, {"id": "III.5.b", "app": "access", "text": "Exportați tabela comp_t într-un registru Excel cu numele comp_te, salvat în directorul examen.", "pts": [[3, "Export realizat"], [2, "Nume comp_te, în examen"]], "sol": {"ms": "Clic dreapta pe comp_t → Export → Excel → folderul examen, nume comp_te.", "lo": "Base: copiați tabela și lipiți în Calc → salvați comp_te.xlsx."}, "note": ""}, {"id": "III.6.a", "app": "sistem", "text": "Redenumiți fișierul comp_n în buget_n și creați în directorul examen o copie a fișierului comp_x cu numele buget_x.", "pts": [[2, "Redenumire buget_n"], [3, "Copie buget_x"]], "sol": {"ms": "F2; Ctrl+C, Ctrl+V → F2.", "lo": "Idem."}, "note": ""}, {"id": "III.6.b", "app": "sistem", "text": "Căutați în directorul examen fișierele al căror nume conține textul comp și salvați o captură a ferestrei cu rezultatele la finalul fișierului comp_w.", "pts": [[1, "Captură"], [4, "Rezultatele căutării vizibile"]], "sol": {"ms": "Caseta Căutare: comp → Alt+PrtScn.", "lo": "Ctrl+F în managerul de fișiere."}, "note": ""}]}];
window.EXTRA_TASKS = [{"id": "A.1", "app": "access", "text": "comp_a: Modificați în tabela comp_t valoarea câmpului Fructoză pentru specia prune în 2,5.", "pts": [[3, "Valoare modificată"], [2, "Înregistrarea corectă"]], "sol": {"ms": "Deschideți comp_t → clic în celulă → scrieți 2,5 → Enter.", "lo": "Base: editare directă în tabel."}, "note": ""}, {"id": "A.2", "app": "access", "text": "comp_a: Creați o interogare cu numele comp_med care afișează, pentru fiecare magazin, media valorilor din câmpul Glucoză.", "pts": [[2, "Interogare comp_med"], [1, "Grupare după Magazin"], [2, "Medie pe Glucoză"]], "sol": {"ms": "Proiectare interogare → Totaluri (Σ) → Magazin: Grupare după, Glucoză: Medie.", "lo": "Base: Funcție: Media."}, "note": ""}, {"id": "A.3", "app": "access", "text": "comp_a: Creați o interogare cu parametru, cu numele comp_param, care la rulare cere numele magazinului și afișează speciile din acel magazin.", "pts": [[2, "Interogare comp_param"], [3, "Criteriul parametru [Introduceți magazinul]"]], "sol": {"ms": "Criterii la Magazin: [Introduceți magazinul].", "lo": "Base: criteriu :magazin."}, "note": ""}, {"id": "A.4", "app": "access", "text": "comp_a: Creați o interogare cu numele comp_top care afișează primele 3 specii cu cea mai mare valoare a câmpului Glucoză.", "pts": [[2, "Interogare comp_top"], [2, "Sortare descrescătoare după Glucoză"], [1, "Valori maxime: 3"]], "sol": {"ms": "Sortare: Descendent la Glucoză; Proiectare → Valori maxime (Return): 3.", "lo": "Base: sortare descrescătoare + Limită 3."}, "note": ""}, {"id": "A.5", "app": "access", "text": "comp_a: Copiați tabela comp_t, doar structura (fără date), cu numele comp_t2.", "pts": [[3, "Tabelă copiată"], [2, "Doar structura, nume comp_t2"]], "sol": {"ms": "Ctrl+C pe comp_t → Ctrl+V → Numai structura → comp_t2.", "lo": "Base: Copiere → Lipire → Doar definiție."}, "note": ""}, {"id": "A.6", "app": "access", "text": "comp_a: Realizați un raport cu numele comp_rs cu toate câmpurile din comp_t, sortat crescător după Specia, cu titlul Conținutul de zaharuri.", "pts": [[2, "Raport comp_rs"], [2, "Sortare după Specia"], [1, "Titlul"]], "sol": {"ms": "Expert raport → toate câmpurile → Sortare: Specia → titlu la final → modificați eticheta de titlu.", "lo": "Base: Expert rapoarte → Sortare → Specia."}, "note": ""}, {"id": "A.7", "app": "access", "text": "comp_a: Creați o tabelă nouă cu numele comp_m, cu câmpurile Cod (Numerotare automată, cheie primară) și Nume_magazin (Text scurt).", "pts": [[2, "Tabelă comp_m"], [2, "Câmpurile și tipurile"], [1, "Cheie primară pe Cod"]], "sol": {"ms": "Creare → Proiectare tabel → Cod: Numerotare automată (cheie) → Nume_magazin: Text scurt → Salvare comp_m.", "lo": "Base: Creare tabel în Vizualizare proiect; Cod: Întreg + Valoare automată."}, "note": ""}, {"id": "A.8", "app": "access", "text": "comp_a: Modificați interogarea comp_q astfel încât să afișeze doar înregistrările cu Glucoză mai mică decât 3.", "pts": [[2, "Interogarea comp_q modificată"], [3, "Criteriul <3 pe Glucoză"]], "sol": {"ms": "comp_q → Vizualizare proiect → Criterii la Glucoză: <3 → Salvare.", "lo": "Base: Editare interogare → criteriu <3."}, "note": ""}, {"id": "A.9", "app": "access", "text": "comp_a: Ascundeți câmpul Magazin în vizualizarea Foaie de date a tabelei comp_t și salvați aspectul tabelei.", "pts": [[3, "Coloana ascunsă"], [2, "Aspect salvat"]], "sol": {"ms": "Clic dreapta pe antetul coloanei → Ascundere câmpuri → Ctrl+S.", "lo": "Base: clic dreapta pe antet → Ascunde coloanele."}, "note": ""}, {"id": "A.10", "app": "access", "text": "comp_a: Aplicați în tabela comp_t un filtru care să afișeze doar înregistrările din Magazin 2 și salvați tabela.", "pts": [[3, "Filtru aplicat"], [2, "Criteriul Magazin 2, salvat"]], "sol": {"ms": "Clic pe o celulă cu Magazin 2 → Selecție → Este egal cu \"Magazin 2\" → Ctrl+S.", "lo": "Base: Filtru automat."}, "note": ""}, {"id": "A.11", "app": "access", "text": "comp_a: Creați o interogare cu numele comp_c2 care afișează Specia și câmpul calculat Diferenta, egal cu Fructoză − Glucoză, doar pentru valori pozitive ale diferenței.", "pts": [[2, "Câmp calculat Diferenta"], [3, "Criteriul >0 pe câmpul calculat"]], "sol": {"ms": "Coloană nouă: Diferenta: [Fructoză]-[Glucoză]; Criterii: >0.", "lo": "Base: \"Fructoză\"-\"Glucoză\" cu alias și criteriu >0."}, "note": ""}, {"id": "A.12", "app": "access", "text": "comp_a: Exportați raportul (sau tabela) comp_t în format PDF, cu numele comp_pdf, în directorul examen.", "pts": [[3, "Fișier PDF creat"], [2, "Nume și locație corecte"]], "sol": {"ms": "Clic dreapta → Export → PDF sau XPS → examen → comp_pdf.", "lo": "Base: deschideți tabela/raportul → Fișier → Export în PDF."}, "note": ""}, {"id": "A.13", "app": "access", "text": "comp_a: Stabiliți pentru câmpul Specia proprietatea Indexat: Da (fără dubluri).", "pts": [[3, "Index aplicat"], [2, "Fără dubluri"]], "sol": {"ms": "Vizualizare proiect → Specia → Indexat: Da (Fără dubluri).", "lo": "Base: Editare → Proiectare index → Unic."}, "note": ""}, {"id": "A.14", "app": "access", "text": "comp_a: Creați o interogare cu numele comp_sau care afișează speciile din Magazin 1 sau Magazin 3.", "pts": [[2, "Interogare comp_sau"], [3, "Condiția SAU corectă"]], "sol": {"ms": "Criterii: \"Magazin 1\", pe rândul „sau”: \"Magazin 3\" (sau In(\"Magazin 1\",\"Magazin 3\")).", "lo": "Base: criteriu pe două rânduri (SAU)."}, "note": ""}];
